// Від Іоана — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Споконвіку було Слово, і Слово було у Бога, і Слово було Бог.","Воно було споконвіку в Бога.","Все через Нього сталось, і без Нього ніщо не сталося, що сталося.","У Ньому було життя, і життя було світлом людям.","І світло в темряві світить, і темрява не огорнула його.","Був чоловік, посланий від Бога; ім’я йому Іоан.","Він прийшов для свідчення, щоб свідчити про Світло, щоб усі увірували через нього.","Він не був світлом, але був посланий, щоб свідчити про Світло.","Було Світло істинне, що освітлює кожну людину, яка приходить у світ.","У світі був, і світ через Нього постав, і світ Його не пізнав.","До своїх прийшов, і свої Його не прийняли.","А тим, які прийняли Його, що вірують в ім’я Його, дав силу дітьми Божими бути,","які не від крови, не від похоті плотської, не від хотіння чоловічого, а від Бога народилися.","І Слово стало плоттю, і вселилося між нами, повне благодаті й істини; і ми бачили славу Його, славу, як Єдинородного від Отця.","Іоан свідчить про Нього і голосно каже: це Той, про Кого я говорив; Той, Хто йде за мною, став попереду мене, бо раніше від мене був.","І від повноти Його ми всі прийняли і благодать на благодать,","бо закон був даний через Мойсея; а благодать і істина через Ісуса Христа сталися.","Бога ніхто не бачив ніколи; Єдинородний Син, Який у лоні Отця, Він явив.","І ось свідчення Іоана, коли юдеї послали з Єрусалима священиків і левитів спитати його: хто ти є?","Він визнав, і не зрікся, і визнав, що: я — не Христос.","І запитали його: то хто ж ти? Чи не Ілля? Він сказав: ні. Ти пророк? Він відповів: ні.","Тоді сказали йому: хто ж ти такий? Щоб нам відповідь дати тим, що послали нас; що ти скажеш про самого себе?","Він сказав: я глас вопіющого в пустелі; приготуйте путь Господеві, як сказав Ісая пророк.","А посланці були від фарисеїв.","І вони запитали його і сказали йому: що ж ти хрестиш, якщо ти не є Христос, ні Ілля, ні пророк?","Іоан сказав їм у відповідь: я хрещу водою; але серед вас стоїть Той, Кого ви не знаєте;","Він гряде за мною, але переді мною був; я недостойний розв’язати ремінь взуття Його.","Це сталося у Вифаварі по той бік Йордану, де хрестив Іоан.","Наступного дня бачить Іоан Ісуса, Який іде до нього, і говорить: ось Агнець Божий, Який бере на себе гріхи світу.","Це Той, про Якого я сказав: за мною гряде Муж, Який переді мною був, бо Він був раніше від мене.","Я не знав Його; але прийшов хрестити водою для того, щоб Він явився Ізраїлеві.","І свідчив Іоан, кажучи: я бачив Духа, Який сходив з неба, мов голуб, і перебував на Ньому.","Я не знав Його; але Той, Хто послав мене хрестити водою, сказав мені: на Кому побачиш Духа, Який сходить і перебуває на Ньому, Той хреститиме Духом Святим.","І я бачив і засвідчив, що Цей є Син Божий.","Наступного дня знову стояв Іоан з двома з його учнів.","І, побачивши Ісуса, Який ішов, сказав: ось Агнець Божий.","Почувши від нього ці слова, обидва учні пішли за Ісусом.","Ісус же, обернувшись і побачивши, що вони йдуть за Ним, говорить їм: чого ви шукаєте? Вони сказали Йому: Равві [що означає: Учителю]! Де Ти живеш?","Говорить їм: підіть і побачите. Вони пішли і побачили, де Він живе; і пробули у Нього той день, а було близько десятої години.","Одним з тих двох, які чули від Іоана про Ісуса і пішли за Ним, був Андрій, брат Симона-Петра.","Він спочатку розшукав брата свого Симона і каже йому: ми знайшли Месію, що означає: Христос.","І привів його до Ісуса. Ісус же, поглянувши на нього, сказав: ти — Симон, син Іони; ти наречешся Кифа, що означає камінь [Петро].","Наступного дня Ісус захотів йти до Галилеї; і знаходить Филипа, і каже йому: йди за Мною.","Филип же був з Вифсаїди, з одного міста з Андрієм і Петром.","Филип знаходить Нафанаїла і каже йому: ми знайшли Того, про Якого писали Мойсей у законі і пророки, Ісуса, сина Йосифа, з Назарета.","Але Нафанаїл сказав йому: чи може щось добре бути з Назарета? Филип говорить йому: піди і подивись.","Ісус, побачивши Нафанаїла, який ішов до Нього, говорить про нього: ось воістину ізраїльтянин, у якому нема лукавства.","Нафанаїл говорить Йому: звідки Ти мене знаєш? Ісус відповів йому: перше ніж покликав тебе Филип, Я бачив тебе під смоковницею.","Нафанаїл відповів Йому: Учителю! Ти — Син Божий, Ти — Цар Ізраїлів.","Ісус сказав йому у відповідь: через те, що Я сказав тобі, що бачив тебе під смоковницею, ти віруєш; більше цього побачиш.","І говорить йому: істинно, істинно кажу вам: віднині побачите небо відкрите і ангелів Божих, які піднімаються і спускаються над Сином Людським."],"x":{"1":"26.8.22|58.1.1-2","3":"0.1.3|25.32.6","5":"53.3.19","6":"50.3.1","9":"31.60.1","11":"50.15.24","12":"62.8.15|65.3.26","13":"53.3.5","14":"50.1.16|50.17.2|53.17.24|64.3.9|75.2.11","15":"50.3.11","16":"66.1.6|68.1.19","17":"1.20.1|62.3.24","18":"1.33.20|58.4.12|71.6.16","19":"53.5.33","20":"53.3.28|54.13.25","23":"31.40.3|50.3.3|51.1.3|52.3.4","29":"1.12.3|31.53.7","31":"51.1.4","32":"50.3.16|51.1.10|52.3.22|53.6.27","42":"50.16.18","45":"0.49.10|4.18.15|25.39.8|31.4.2|31.7.14|31.9.6|31.40.11|31.45.8|31.53.1|32.23.5|32.33.14|36.34.23|36.37.24|37.9.24|43.5.2|48.9.9","51":"0.28.12"}},{"v":["На третій день було весілля в Кані галилейській, і Мати Ісусова була там.","Був також запрошений на весілля Ісус з учениками Його.","Коли не вистачило вина, Мати Ісуса каже Йому: вина не мають.","Ісус говорить Їй: що Мені і Тобі, Жоно? Ще не прийшов час Мій.","Мати Його говорить слугам: що скаже Він вам, те зробіть.","Було ж тут шість кам’яних водоносів, що стояли за звичаєм для очищення юдейського, кожен вміщав по дві чи по три міри.","Ісус говорить їм: наповніть посудини водою. І наповнили їх до верху.","І говорить їм: тепер зачерпніть і несіть до розпорядника весілля. І понесли.","Коли ж розпорядник покуштував воду, що стала вином [а він не знав, звідки це вино, знали ж тільки слуги, які набирали воду], тоді розпорядник кличе жениха","і говорить йому: кожна людина спочатку добре вино подає, а коли нап’ються, тоді гірше; а ти добре вино зберіг аж досі.","Так поклав Ісус початок чудесам у Кані галилейській і явив славу Свою; і увірували в Нього ученики Його.","Після цього прийшов Ісус до Капернаума, Сам і Мати Його, і брати Його, і ученики Його; і пробули там небагато днів.","Наближалася Пасха юдейська, і Ісус прийшов до Єрусалима.","І знайшов, що в храмі продавали волів, овець і голубів, і сиділи міняльники грошей.","І, зробивши бич з вірьовок, вигнав з храму всіх, овець і волів; і розсипав гроші міняльників, а столи їхні поперекидав.","І сказав продавцям голубів: візьміть це звідси і не робіть дому Отця Мого домом торгівлі.","При цьому ученики Його згадали, що написано: ревність до дому Твого з’їдає Мене.","На це юдеї сказали Йому: яке знамення покажеш нам, що маєш владу так чинити?","Ісус сказав їм у відповідь: зруйнуйте храм цей, і Я за три дні поставлю його.","На це сказали юдеї: сорок шість років будувався храм цей, а Ти за три дні поставиш його?","Він же говорив про храм тіла Свого.","Коли ж Він воскрес з мертвих, то згадали ученики Його, що Він казав їм це, і повірили Писанню і слову, яке сказав Ісус.","І коли Він був у Єрусалимі на святі Пасхи, багато хто увірував в ім’я Його, побачивши чудеса, які Він творив.","Але Сам Ісус не ввіряв Себе їм, бо знав усіх;","і не треба було Йому, щоб хтось засвідчив про людину, бо Сам знав, що було в людині."],"x":{"13":"4.16.1","14":"50.21.12|51.11.15|52.19.45","17":"25.68.10","19":"50.26.61|50.27.40|51.14.58|51.15.29","22":"25.15.8|31.55.3|50.17.23|54.2.25|54.13.34","24":"50.9.4|51.2.8","25":"25.7.10|32.11.20|53.6.64"}},{"v":["Був же чоловік з фарисеїв на ім’я Никодим, начальник юдейський.","Він уночі прийшов до Ісуса і сказав Йому: Учителю, ми знаємо, що Ти Учитель, Який прийшов від Бога; бо ніхто не може таких чудес творити, які Ти твориш, якби Бог не був з ним.","Ісус сказав йому у відповідь: істинно, істинно кажу тобі: якщо хто не народиться звище, не може бачити Царства Божого.","Никодим говорить Йому: як може людина народитися, будучи старою? Хіба вона може вдруге ввійти в утробу матері своєї і народитися?","Ісус відповів: істинно, істинно кажу тобі: якщо хто не народиться водою і Духом, не може увійти в Царство Боже.","Народжене від плоті є плоть, а народжене від Духа є дух.","Не дивуйся тому, що Я сказав тобі; треба вам народитися звище.","Дух дише де хоче, і голос його чуєш, але не знаєш, звідки він приходить і куди йде: так буває з кожною людиною, народженою від Духа.","Никодим сказав Йому у відповідь: як це може бути?","Ісус відповів йому і сказав: ти — учитель Ізраїлів, і чи цього не знаєш?","Істинно, істинно кажу тобі: Ми говоримо про те, що знаємо, і свідчимо про те, що бачили, а ви свідчення Нашого не приймаєте.","Якщо Я сказав вам про земне і ви не вірите, то як повірите, коли буду говорити вам про небесне?","Ніхто не сходив на небо, тільки Той, Хто зійшов з небес, Син Людський, Сущий на небесах.","І як Мойсей підніс змія в пустелі, так належить піднестися Синові Людському,","щоб кожен, хто вірує в Нього, не загинув, але мав життя вічне.","Бо так полюбив Бог світ, що віддав і Сина Свого Єдинородного, щоб усякий, хто вірує в Нього, не загинув, а мав життя вічне.","Бо не послав Бог Сина Свого в світ, щоб судити світ, а щоб світ спасся через Нього.","Хто вірує в Нього, не буде осуджений, а хто не вірує, вже осуджений, бо не увірував в ім’я Єдинородного Сина Божого.","Суд полягає в тому, що світло прийшло у світ, а люди полюбили темряву більше, ніж світло, бо діла їхні були лихі;","бо кожен, хто чинить зло, ненавидить світло і не йде до світла, щоб не викрилися діла його, бо вони злі.","А хто чинить правду, йде до світла, щоб відкрилися діла його, бо вони чинилися в Бозі.","Після цього прийшов Ісус з учениками Своїми в Юдейську землю, і там жив з ними і хрестив.","Іоан же хрестив в Еноні, поблизу Салима, бо там було багато води; і приходили туди, і хрестилися,","бо Іоан ще не був посаджений до в’язниці.","Тоді виникла суперечка учнів Іоанових з юдеями про очищення.","І прийшли до Іоана і сказали йому: учителю! Той, Який був з тобою по той бік Йордану, про Якого ти свідчив, ось Він хрестить, і всі йдуть до Нього.","Іоан сказав у відповідь: не може людина приймати на себе нічого, якщо не буде дано їй з неба.","Ви самі мені свідчите про те, що я сказав: я не Христос, але я посланий перед Ним.","Хто має наречену, той жених, а друг жениха, стоячи і слухаючи його, радістю радіє, чуючи голос жениха. Отже, ця радість моя сповнилася.","Йому належить рости, а мені умалятися.","Хто приходить згори, Той над усіма є, хто від землі — земний є і по-земному говорить. Хто з неба йде, Той над усіма є.","І що Він бачив і чув, про те й свідчить; і свідчення Його ніхто не приймає.","Хто прийняв Його свідчення, той ствердив, що Бог є істинний.","Бо Той, Кого послав Бог, говорить слова Божі; бо без міри дає Бог Духа.","Отець любить Сина і все дав у руки Йому.","Хто вірує в Сина, має життя вічне, а хто не вірує в Сина, не побачить життя, але гнів Божий перебуває на ньому."],"x":{"1":"53.7.50|53.19.39","3":"55.1.18|56.1.23|64.5.17|65.6.15|73.3.5","6":"62.8.5","8":"68.3.3","13":"26.30.4|53.6.62","14":"3.21.9|53.12.32","16":"31.9.6|51.16.16|53.6.40|58.4.9-10","19":"53.1.5|53.8.12","26":"53.1.27","27":"53.6.65","28":"53.1.20|54.13.25","29":"50.22.2|66.5.25:27","31":"53.8.23|62.9.5|66.1.21","32":"53.8.26","33":"58.5.10|62.3.4","34":"53.1.16|66.4.7","35":"37.7.14|50.28.18","36":"45.2.4"}},{"v":["Коли ж Ісус довідався про почуте фарисеями, що Ісус більше збирає учеників і хрестить, ніж Іоан, —","хоч Ісус Сам не хрестив, а ученики Його, —","то залишив Юдею і знову пішов до Галилеї.","Належало ж Йому проходити через Самарію.","Ось приходить Він до міста самарянського, що зветься Сихар, поблизу землі, яку Яків дав синові своєму Йосифу.","Була там криниця Якова. Ісус, утомившись з дороги, сів біля криниці, а було близько шостої години.","Приходить жінка з Самарії набрати води. Ісус говорить їй: дай Мені напитися.","Бо ученики Його пішли до міста, щоб купити їжі.","Жінка-самарянка каже Йому: як Ти, будучи юдеєм, просиш напитися у мене, самарянки? Адже юдеї не знаються з самарянами.","Ісус сказав їй у відповідь: якби ти знала дар Божий і Хто говорить тобі: дай Мені напитися, — то ти попросила б у Нього, і Він дав би тобі води живої.","Говорить Йому жінка: Господи! Тобі і зачерпнути нема чим, а криниця глибока; звідки ж Ти маєш воду живу?","Невже Ти більший за отця нашого Якова, який дав нам криницю оцю і сам з неї пив, і діти його, і худоба його?","Ісус сказав їй у відповідь: всякий, хто п’є цю воду, знову буде спраглим.","А хто питиме воду, яку дам Я йому, той не буде спраглим повік; але вода, яку дам йому Я, стане в ньому джерелом води, що тече в життя вічне.","Говорить Йому жінка: Господи, дай мені цієї води, щоб я не хотіла пити і не приходила сюди черпати.","Ісус говорить їй: іди поклич чоловіка свого і приходь сюди.","Жінка сказала Йому у відповідь: не маю я чоловіка. Говорить їй Ісус: правду сказала, що чоловіка не маєш,","бо п’ять чоловіків мала, і той, кого маєш тепер, не чоловік тобі; це ти правду сказала.","Жінка говорить Йому: Господи, бачу, що Ти пророк.","Батьки наші поклонялися на цій горі, а ви говорите, що місце, де належить поклонятися, знаходиться в Єрусалимі.","Ісус говорить їй: жінко, повір Мені, що надходить час, коли будете поклонятись Отцеві, і не на цій горі, і не в Єрусалимі.","Ви кланяєтеся тому, чого не знаєте, а ми кланяємося тому, що знаємо, бо спасіння — від юдеїв.","Але прийде час, і нині вже є, коли справжні поклонники кланятимуться Отцеві духом та істиною, бо таких поклонників шукає Отець Собі.","Бог є Дух, і тим, що поклоняються Йому, належить поклонятися духом та істиною.","Жінка говорить Йому: знаю, що прийде Месія, званий Христос; коли Він прийде, сповістить нам усе.","Ісус сказав їй: це Я, Який розмовляю з тобою.","В цей час прийшли ученики Його і здивувалися, що Він розмовляє з жінкою; проте ніхто не сказав: чого Тобі треба? Або: про що говориш з нею?","Тоді жінка залишила свій водонос, пішла до міста і сказала людям:","ідіть, побачите Чоловіка, Який сказав мені про все, що я зробила; чи не Він Христос?","Вони вийшли з міста і пішли до Нього.","Тим часом ученики просили Його, кажучи: Учителю, їж.","Він же сказав їм: Я маю їжу, якої ви не знаєте.","Тому ученики говорили між собою: хіба хто приніс Йому їсти?","Ісус говорить їм: Моя їжа є творити волю Того, Хто послав Мене, і звершити діло Його.","Чи не кажете ви, що ще чотири місяці, і настануть жнива? А Я говорю вам: зведіть очі ваші і погляньте на ниви, як вони пополовіли і готові до жнив.","Хто жне, той одержує нагороду і збирає плід у життя вічне, щоб і сівач, і жнець разом раділи.","Бо про це є правдиве слово: один сіє, а інший жне.","Я послав вас жати те, над чим ви не працювали: інші працювали, а ви ввійшли в їхню працю.","І багато самарян з міста того увірували в Нього за словом жінки, яка засвідчила, що Він сказав їй про все, що вона зробила.","І тому, коли прийшли до Нього самаряни, то просили Його побути в них; і Він пробув там два дні.","І ще більше увірувало в Нього за Його словом.","А жінці тій говорили: вже не через твої слова віруємо, бо самі чули і знаємо, що Він істинно Спаситель світу, Христос.","Як минуло ж два дні, Він вийшов звідти і пішов до Галилеї,","бо Сам Ісус свідчив, що пророк у своїй батьківщині не має чести.","Коли Він прийшов до Галилеї, то галилеяни прийняли Його, побачивши все, що Він зробив в Єрусалимі під час свята, бо і вони ходили на свято.","Отже, Ісус знову прийшов до Кани галилейської, де перетворив воду на вино. Був у Капернаумі царедворець, у якого син був хворий.","Він, почувши, що Ісус прийшов з Юдеї в Галилею, прийшов до Нього і просив Його прийти і зцілити його сина, який був при смерті.","Ісус сказав йому: ви не увіруєте, якщо не побачите знамень і чудес.","Царедворець говорить Йому: Господи! Прийди, поки не помер син мій.","Ісус каже йому: іди, син твій живий. І повірив чоловік слову, яке сказав йому Ісус, і пішов.","Одразу, як тільки він входив, зустріли його слуги його і сказали: син твій живий.","Він спитав у них: о котрій годині стало йому легше? Йому сказали: вчора о сьомій годині покинула його гарячка.","Зрозумів батько, що це був саме той час, коли Ісус сказав йому: син твій живий, і увірував сам і весь дім його.","Це вже друге чудо сотворив Ісус, повернувшись з Юдеї в Галилею."],"x":{"1":"53.3.26","5":"0.33.19|0.48.22|5.24.32","9":"11.17.24|52.9.53","10":"31.12.3|31.44.3|48.14.8","20":"4.12.6|4.16.6|10.9.3","22":"0.12.3|11.17.29|31.2.3|62.9.5","24":"64.3.17|67.3.3","35":"50.9.37|52.10.2","43":"50.4.12|51.1.14","44":"50.13.57|51.6.4|52.4.24","46":"53.2.11"}},{"v":["Після цього було юдейське свято, і прийшов Ісус до Єрусалима.","В Єрусалимі ж біля Овечих воріт є купальня, що по-єврейськи зветься Вифезда, яка мала п’ять критих входів.","У них лежало багато хворих, сліпих, кривих, сухих, що чекали руху води,","бо ангел Господній щороку сходив у купальню і збурював воду; і хто перший входив після збурення води, той одужував, хоч би яку недугу мав.","Тут був чоловік, який хворів тридцять вісім років.","Ісус, побачивши, що він лежить, і знаючи, що вже довго хворіє, говорить йому: чи хочеш бути здоровим?","Недужий відповів Йому: так, Господи! Але людини не маю, щоб, коли збуриться вода, опустила мене в купальню; коли ж я приходжу, інший вже поперед мене входить.","Ісус говорить йому: встань, візьми постіль твою і ходи.","І він одразу одужав, взяв постіль свою і пішов. Була ж субота у той день.","Тому юдеї говорили зціленому: сьогодні субота, і не слід було тобі брати постіль свою.","Він відповів їм: Хто зцілив мене, Той сказав мені: візьми постіль твою і ходи.","Його спитали: Хто Той Чоловік, Який сказав тобі: візьми постіль твою і ходи?","А зцілений не знав, хто Він, бо Ісус зник у натовпі, що був на тому місці.","Потім Ісус зустрів його у храмі і сказав йому: ось ти одужав; не гріши більше, щоб з тобою не сталося чого гіршого.","Чоловік цей пішов і сказав юдеям, що Той, Хто зцілив його, є Ісус.","І почали юдеї переслідувати Ісуса, і шукали, як Його вбити за те, що творив такі діла в суботу.","Ісус же говорив їм: Отець Мій донині робить, і Я роблю.","Юдеї ще більше вишукували, як Його вбити за те, що Він не тільки порушував суботу, але й Отцем Своїм називав Бога, рівняючи Себе до Бога.","На це Ісус сказав: істинно, істинно говорю вам: Син нічого не може творити Сам від Себе, якщо не побачить, як творить Отець; бо, що Він творить, те так само творить і Син.","Бо Отець любить Сина і показує Йому все, що Сам творить; і покаже Йому діла більші від цих, щоб ви дивувались.","Бо, як Отець воскрешає мертвих і оживляє, так і Син оживляє, кого хоче.","Бо Отець не судить нікого, а весь суд віддав Синові,","щоб усі шанували Сина, як шанують Отця; а хто не шанує Сина, той не шанує і Отця, Який послав Його.","Істинно, істинно кажу вам: хто слово Моє слухає і вірить у Того, Хто послав Мене, той має вічне життя і на суд не приходить, а перейшов від смерти до життя.","Істинно, істинно кажу вам, що настане час, і нині вже є, коли мертві почують голос Сина Божого і, почувши, оживуть.","Бо як Отець має життя в Самому Собі, так і Синові дав мати життя в Самому Собі.","І дав Йому владу суд творити, бо Він є Син Людський.","Не дивуйтесь цьому, бо настає час, коли всі, хто в гробах, почують голос Сина Божого;","і вийдуть ті, хто творив добро, у воскресіння життя, а ті, хто чинив зло, — у воскресіння суду.","Я нічого не можу творити Сам від Себе. Як чую, так і суджу, і суд Мій праведний; бо не шукаю Моєї волі, а волі Отця, Який послав Мене.","Коли Я свідчу Сам про Себе, то свідчення Моє не є істинне.","Є інший, який свідчить про Мене; і Я знаю, що істинне те свідчення, яким він свідчить про Мене.","Ви посилали до Іоана, і він засвідчив істину.","А втім, Я не від людини приймаю свідчення, але говорю це для того, щоб ви спаслися.","Він був світильник, який горів і світив; ви ж хотіли короткий час порадуватися при світлі його.","Я ж маю свідчення більше за Іоанове: бо діла, які Отець дав Мені звершити, саме ці діла, які Я творю, свідчать про Мене, що Отець Мене послав.","І Отець, Який послав Мене, Сам засвідчив про Мене. А ви ні голосу Його ніколи не чули, ні лиця Його ніколи не бачили;","і не маєте слова Його, яке перебувало б у вас; бо ви не віруєте в Того, Кого Він послав.","Дослідіть Писання, бо ви сподіваєтесь через них мати життя вічне; а вони свідчать про Мене.","Але ви не хочете прийти до Мене, щоб мати життя.","Не приймаю слави від людей,","але знаю вас: ви не маєте в собі любови до Бога.","Я прийшов в ім’я Отця Мого, і не приймаєте Мене; а коли інший прийде в ім’я своє, того приймете.","Як ви можете вірувати, коли приймаєте славу один від одного, а слави, яка від Єдиного Бога, не шукаєте?","Не думайте, що Я буду звинувачувати вас перед Отцем: є той, хто вас звинувачує, — Мойсей, на якого ви уповаєте.","Бо якби ви вірили Мойсеєві, то повірили б і Мені, тому що він писав про Мене.","Якщо ж його Писанням не вірите, то як повірите Моїм словам?"],"x":{"10":"32.17.22","17":"53.9.4|53.14.10","18":"53.7.30","22":"50.28.18|54.17.31|56.4.5","23":"58.2.23","27":"37.7.14","28":"31.26.19|37.12.2|63.15.52","29":"50.25.46|76.14.11","30":"50.26.39","32":"50.3.17","33":"53.1.19","36":"53.10.25","37":"4.4.12|50.3.17","39":"4.18.15|31.9.6|31.53.1","40":"53.1.11|53.3.19","44":"53.12.43","46":"0.3.15|0.12.3|0.18.18|0.49.10|4.18.15"}},{"v":["Після цього пішов Ісус на той бік Тиверіадського моря в Галилеї.","За Ним ішло багато народу, бо бачили чудеса, які Він творив над недужими.","Ісус зійшов на гору і сидів там з учениками Своїми.","Наближалася ж Пасха, юдейське свято.","Ісус, звівши очі і побачивши, що багато народу йде до Нього, говорить Филипові: за що нам купити хлібів, щоб їх нагодувати?","Говорив же це, випробовуючи його, бо Сам знав, що хотів зробити.","Филип відповів Йому: і на двісті динаріїв не вистачить хліба, щоб кожний з них хоч трохи одержав.","Один з учеників Його, Андрій, брат Симона-Петра, говорить Йому:","тут є один юнак, який має п’ять хлібів ячмінних і дві рибини; але що то на таку безліч?","Ісус сказав: звеліть людям сісти. Було ж на тому місці багато трави. Отже, сіло людей близько п’яти тисяч.","Ісус, взявши хліби і воздавши хвалу, роздав ученикам, а ученики — тим, що сиділи, також і риби, скільки хто хотів.","І коли наситилися, то сказав ученикам Своїм: зберіть залишки, щоб нічого не пропало.","І зібрали, і наповнили дванадцять кошиків залишками від п’яти ячмінних хлібів, що їли.","Тоді люди, побачивши, яке чудо сотворив Ісус, сказали: це воістину Той Пророк, Який має прийти у світ.","Ісус же, дізнавшись, що хочуть прийти, несподівано взяти Його і зробити царем, знову пішов на гору один.","Коли ж настав вечір, то ученики Його зійшли до моря.","І, сівши в човен, попливли на другий бік моря до Капернаума. Було вже темно, а Ісус не приходив до них.","Дув сильний вітер, і море хвилювалося.","Пропливши стадій близько двадцяти п’яти чи тридцяти*, вони побачили Ісуса, Який ішов по морю і вже наближався до човна, і злякались.","Але Він сказав їм: це Я, не бійтеся.","Вони хотіли взяти Його в човен; і у ту ж мить човен пристав до берега, куди пливли.","Наступного дня народ, який стояв по той бік моря, бачив, що іншого човна не було там, крім того, в який увійшли ученики Його, і що Ісус не входив у човен з учениками Своїми, а відпливли одні ученики Його.","Тим часом прийшли з Тиверіади інші човни до того місця, де їли хліб за благословенням Господнім.","Коли ж люди побачили, що тут немає ні Ісуса, ні учеників Його, то посідали в човни і попливли до Капернаума, шукаючи Ісуса.","І, знайшовши Його по той бік моря, сказали Йому: Учителю, коли Ти прибув сюди?","Ісус сказав їм у відповідь: істинно, істинно кажу вам: ви шукаєте Мене не тому, що бачили чудеса, а тому, що їли хліб і наситились.","Дбайте не про їжу тлінну, а про їжу, яка залишається на життя вічне, яку дасть вам Син Людський, бо назнаменував Його Отець, Бог.","Вони сказали Йому: що нам робити, щоб чинити діла Божі?","Ісус сказав їм у відповідь: ось діло Боже, щоб ви увірували в Того, Кого Він послав.","На це вони сказали Йому: яке ж знамення Ти створиш, щоб ми побачили і увірували в Тебе? Що Ти чиниш?","Батьки наші їли манну в пустелі, як написано: хліб з неба дав їм їсти.","Ісус же сказав їм: істинно, істинно кажу вам: не Мойсей дав вам хліб з неба, але Отець Мій дає вам істинний хліб з небес.","Бо хліб Божий є той, який сходить з небес і дає життя світові.","На це сказали Йому: Господи! Завжди давай нам хліб цей.","Ісус сказав їм: Я є хліб життя; хто приходить до Мене, не відчуватиме голоду, і хто вірує в Мене, ніколи не матиме спраги.","Але Я вам сказав, що ви хоч і бачили Мене, та не віруєте.","Усе, що дає Мені Отець, до Мене прийде; і того, хто приходить до Мене, Я не вижену геть.","Бо Я зійшов з небес не для того, щоб творити волю Мою, а волю Отця, Який послав Мене.","Воля ж Отця, Який послав Мене, є та, щоб з усього, що Він дав Мені, нічого не погубити, а все те воскресити в останній день.","Воля Того, Хто послав Мене, є та, щоб кожен, хто бачить Сина і вірує в Нього, мав життя вічне; і Я воскрешу його в останній день.","Ремствували на Нього юдеї за те, що Він казав: Я є хліб, який зійшов з небес.","І говорили: чи це не Ісус, син Йосифів, батька і матір Якого ми знаємо? Як же говорить Він: Я зійшов з небес?","Ісус сказав їм у відповідь: не ремствуйте між собою.","Ніхто не може прийти до Мене, якщо Отець, Який послав Мене, не залучить його; і Я воскрешу його в останній день.","У пророків написано: і будуть усі навчені Богом. Кожен, хто чув Отця і навчився, приходить до Мене.","Це не значить, що хтось бачив Отця, хіба лише Той, Хто від Бога; Він бачив Отця.","Істинно, істинно кажу вам: хто вірує в Мене, має життя вічне.","Я є хліб життя.","Батьки ваші їли манну в пустелі — й померли.","Це ж є хліб, який сходить з небес, той, хто його їсть, не помре.","Я — хліб живий, який зійшов з небес; хто їсть цей хліб, житиме вічно; хліб же, який Я дам, є Плоть Моя, яку Я віддам за життя світу.","Тоді юдеї почали сперечатися між собою, кажучи: як Він може дати нам Плоть Свою їсти?","Ісус же сказав їм: істинно, істинно кажу вам: якщо не будете споживати Плоті Сина Людського і не питимете Його Крови, то не будете мати життя в собі.","Хто їсть Мою Плоть і п’є Мою Кров, має життя вічне, і Я воскрешу його в останній день.","Бо Плоть Моя є істинною їжею, і Кров Моя є істинним питтям.","Хто їсть Мою Плоть і п’є Мою Кров, в Мені перебуває, і Я в ньому.","Як послав Мене Живий Отець, — і Я живу Отцем, — так і той, хто їсть Мене, житиме через Мене.","Цей і є хліб, який зійшов з небес. Не так, як батьки ваші їли манну і померли; хто їсть хліб цей, житиме повік.","Це Він говорив, навчаючи у синагозі, в Капернаумі.","Багато хто з учеників Його, слухаючи те, говорили: жорстоке це слово! Хто може це слухати?","Але Ісус, знаючи Сам у Собі, що ученики Його ремствують на те, сказав їм: чи це спокушає вас?","А що ж, коли побачите Сина Людського, Який возноситься туди, де був раніш?","Дух оживляє; плоть аніскільки не допомагає.","Але є між вами деякі, що не вірують. Бо Ісус знав з самого початку, хто не вірує і хто зрадить Його.","І сказав: Я для того і говорив вам, що ніхто не може прийти до Мене, якщо те не буде дано йому від Отця Мого.","Відтоді багато з учеників Його відійшли від Нього і вже з Ним не ходили.","Тоді Ісус сказав дванадцятьом: чи не хочете відійти і ви?","Симон-Петро відповів Йому: Господи, до кого нам іти? Ти маєш слова життя вічного,","і ми увірували і пізнали, що Ти Христос, Син Бога Живого.","Ісус відповів їм: чи не дванадцять Я обрав вас? Але один з вас є диявол.","Це говорив Він про Іуду Симонового Іскаріота, бо той мав зрадити Його, хоч був одним з дванадцятьох."],"x":{"4":"1.12.18","5":"50.14.16|51.6.35-36|52.9.12","13":"51.8.19","14":"4.18.15|50.11.3","17":"50.14.22|51.6.47","27":"50.3.17|53.1.32|53.10.36","29":"53.17.3|58.3.23","31":"25.77.24|1.16.14-15|3.11.7|29.16.20|63.10.3","35":"53.4.14|53.7.37","38":"50.26.39|53.8.29","39":"53.10.28","42":"50.13.55","45":"31.54.13|32.31.34","46":"50.11.27","49":"53.6.31","53":"50.26.26","62":"50.26.64|53.3.13|66.4.8","63":"62.8.2|64.3.6","64":"51.2.8|53.2.24","65":"53.3.27","69":"50.16.16|51.8.29|52.9.20","70":"52.6.13"},"n":{"19":["Приблизно 5 км."]}},{"v":["Після цього Ісус ходив Галилеєю, бо не хотів ходити по Юдеї, тому що шукали юдеї, як вбити Його.","Наближалося свято юдейське — ставлення кущів.","Тоді брати Його сказали Йому: вийди звідси та іди до Юдеї, щоб і ученики Твої бачили діла, які Ти твориш.","Бо ніхто не робить щось таємно, коли сам домагається бути відомим. Якщо Ти твориш такі діла, яви Себе світові.","Бо і брати Його не вірували в Нього.","На це Ісус сказав їм: Мій час ще не настав, час же вам завжди готовий.","Не може світ ненавидіти вас, а Мене ненавидить, бо Я свідчу про нього, що діла його злі.","Ви йдіть на свято це, а Я ще не піду на це свято, бо час Мій ще не настав.","Сказавши це їм, залишився в Галилеї.","Але коли брати Його прийшли на свято, тоді і Він прийшов, та не явно, а ніби таємно.","Юдеї ж шукали Його на святі і говорили: де Він?","І багато було розмов про Нього в народі. Одні говорили, що Він добрий, інші казали, що ні, Він зваблює народ.","Проте ніхто не говорив про Нього відкрито, бо боялись юдеїв.","У переполовення свята Ісус увійшов у храм і навчав.","І дивувалися юдеї, кажучи: як Він знає Писання, не вчившись?","Ісус сказав їм у відповідь: Моє вчення — не Моє, а Того, Хто послав Мене;","хто хоче творити волю Його, той довідається про це вчення, чи воно від Бога, чи Я Сам від Себе кажу.","Хто говорить сам від себе, той шукає слави собі, а Хто шукає слави Тому, Хто послав Його, Той є істинний, і неправди немає в Ньому.","Чи не дав вам Мойсей закон? І ніхто з вас не виконує закону. Чого ж шукаєте, як вбити Мене?","Народ сказав у відповідь: чи не біс у Тобі? Хто хоче Тебе вбити?","Ісус далі сказав їм: одне діло зробив Я, і ви всі дивуєтеся.","Мойсей дав вам обрізання [хоч воно не від Мойсея, а від отців], і в суботу ви обрізуєте чоловіка.","Якщо в суботу приймає чоловік обрізання, щоб не порушити закону Мойсеєвого, — то чому на Мене ремствуєте за те, що Я всього чоловіка зцілив у суботу?","Не судіть з вигляду, а судіть судом справедливим.","Тут деякі з єрусалимлян говорили: чи не Той це, Якого хочуть убити?","Ось Він говорить відкрито, і нічого не кажуть Йому; чи не переконалися начальники, що Він справді Христос?","Але ж ми знаємо, звідки Він; Христос же, коли прийде, ніхто не знатиме, звідки Він.","Тоді Ісус, навчаючи, голосно заговорив у храмі: і Мене знаєте, і знаєте звідки Я; і Я прийшов не Сам від Себе, але є істинний Той, Хто послав Мене, Якого ви не знаєте.","Я ж знаю Його, бо Я від Нього, і Він послав Мене.","І хотіли схопити Його, але ніхто не наклав на Нього руки, бо ще не настав час Його.","Багато ж з народу увірували в Нього і говорили: коли Христос прийде, невже створить більші чудеса, ніж Цей створив?","Фарисеї почули, що таке говорить про Нього народ, і послали фарисеї та первосвященики слуг схопити Його.","Ісус же сказав їм: ще недовго бути Мені з вами, і Я піду до Того, Хто Мене послав.","Шукатимете Мене, і не знайдете; і де буду Я, туди ви не зможете прийти.","При цьому юдеї говорили між собою: куди Він хоче йти, що ми не знайдемо Його? Чи не хоче Він іти в еллінське розсіяння і вчити еллінів?","Що означають слова ці, які Він сказав: будете шукати Мене і не знайдете; і де Я буду, туди ви не зможете прийти?","В останній же великий день свята стояв Ісус і голосно говорив: хто спраглий, нехай іде до Мене і п’є.","Хто вірує в Мене, у того, як сказано в Писанні, з утроби його потечуть ріки води живої.","Це сказав Він про Духа, Якого мали прийняти віруючі в ім’я Його; бо ще не було на них Духа Святого, оскільки Ісус ще не був прославлений.","Багато ж з народу, почувши ці слова, говорили: Він воістину пророк.","Інші говорили: Це Христос. А ще інші казали: хіба з Галилеї Христос прийде?","Чи не сказано в Писанні, що Христос прийде з роду Давидового і з Вифлеєма, з того міста, звідки був Давид?","Отже, виникла в народі через Нього незгода.","Деякі з них хотіли схопити Його; але ніхто не наклав на Нього рук.","І слуги повернулися до первосвящеників і фарисеїв; і дорікали їм: чому не привели Його?","Слуги відповіли: ніколи не говорила людина так, як Цей Чоловік.","Фарисеї ж сказали їм: невже і ви спокусилися?","Хіба увірував у Нього хтось з начальників або з фарисеїв?","Але цей народ, що не знає закону, проклятий він.","Никодим, один з них, який приходив до Нього вночі, говорить їм:","хіба закон наш судить людину, якщо раніше не вислухають її і не дізнаються, що вона робить?","На це сказали йому: чи й ти не з Галилеї? Роздивись і побачиш, що пророк з Галилеї не приходить.","І кожний пішов до свого дому."],"x":{"2":"2.23.34","7":"53.3.19","12":"53.9.16","13":"53.12.42","16":"53.8.28|53.12.49|53.14.24","17":"53.8.47","19":"1.20.1|53.5.18","22":"0.17.10|2.12.3","24":"4.1.17|4.16.19","27":"50.13.55","28":"53.8.42","30":"53.8.20","31":"53.8.30","34":"53.13.33","37":"2.23.36|53.4.14|76.22.17","38":"31.12.3|39.3.18","39":"31.44.3|39.2.28|48.12.10|54.2.17:33","40":"50.26.5","42":"43.5.2|50.2.6|52.2.4","43":"53.9.16","50":"53.3.1","51":"4.1.17|4.17.8"}},{"v":["Ісус же пішов на гору Елеонську.","А вранці знову прийшов у храм, і весь народ ішов до Нього. Він сів і навчав їх.","Приводять книжники і фарисеї до Нього жінку, схоплену під час перелюбу, і, поставивши її посередині, кажуть Йому:","Учителю, цю жінку взяли нині на перелюбі;","а Мойсей в законі повелів нам побивати таких камінням; а Ти що скажеш?","Говорили ж це, спокушаючи Його, щоб знайти, за що Його звинуватити. Але Ісус, нахилившись додолу, пальцем писав по землі, не звертаючи на них уваги.","Коли ж продовжували запитувати Його, Він, підвівшись, сказав їм: хто з вас без гріха, перший кинь у неї камінь.","І знов, нахилившись додолу, писав на землі.","Вони ж, почувши це, докорені совістю, почали виходити один за одним, починаючи від старших до останніх; і залишився один Ісус і жінка, яка стояла посередині.","Ісус, підвівшись і нікого не побачивши, крім жінки, сказав їй: жінко! Де ті, що звинувачували тебе? Ніхто тебе не осудив?","Вона відповіла: ніхто, Господи. Ісус сказав їй: і Я не осуджую тебе; іди, і віднині більше не гріши.","Ісус знову говорив до народу, кажучи: Я — Світло для світу; хто піде вслід за Мною, той не ходитиме в темряві, а матиме світло життя.","Тоді фарисеї сказали Йому: Ти Сам про Себе свідчиш, і свідчення Твоє неправдиве.","Ісус сказав їм у відповідь: якщо і Сам про Себе свідчу, свідчення Моє правдиве, бо Я знаю, звідки прийшов і куди йду; а ви не знаєте, звідки Я і куди йду.","Ви судите за плоттю; а Я не суджу нікого.","А якщо і суджу Я, то суд Мій праведний, бо Я не один, а Я і Отець, Який Мене послав.","У законі вашому написано, що свідчення двох людей є правдиве.","Я Сам свідчу про Себе, і свідчить про Мене Отець, Який Мене послав.","Тоді сказали Йому: де Твій Отець? Ісус відповів: ви не знаєте ні Мене, ні Отця Мого; якби ви знали Мене, то знали б і Отця Мого.","Ці слова говорив Ісус біля скарбниці, коли навчав у храмі; і ніхто не взяв Його, бо ще не прийшов час Його.","Знову сказав їм Ісус: Я відходжу, і будете шукати Мене, і помрете в гріху вашому. Куди Я йду, туди ви не можете прийти.","Говорили ж юдеї: невже Він уб’є Сам Себе, що каже: куди Я іду, ви не можете прийти?","Він сказав їм: ви від нижніх, Я ж від вишніх; ви від світу цього, Я ж не від цього світу.","Тому Я сказав вам, що ви помрете в гріхах ваших. Бо якщо не увіруєте, що це Я, то помрете в гріхах ваших.","Тоді сказали Йому: Хто ж Ти? Ісус відповів їм: Початок всього, що й кажу вам.","Багато чого маю говорити і судити про вас, але Той, Хто послав Мене, істинний є, і що почув Я від Нього, те й кажу світові.","Не зрозуміли, що Він говорив їм про Отця.","Сказав же їм Ісус: коли піднесете Сина Людського, тоді зрозумієте, що це Я, і що нічого не роблю від Себе, а як навчив Мене Отець Мій, так і говорю.","Той, Хто послав Мене, є зі Мною; Отець не залишив Мене одного, бо Я завжди роблю угодне Йому.","Коли Він це говорив, багато хто увірував у Нього.","Тоді Ісус сказав юдеям, які увірували в Нього: якщо будете перебувати в слові Моєму, то ви істинно будете Моїми учениками;","і пізнаєте істину, і істина визволить вас.","Йому відповіли: ми рід Авраамів, і ніколи не були рабами нікому, як же Ти кажеш: станете вільними?","Ісус відповів їм: істинно, істинно кажу вам, що кожен, хто чинить гріх, є раб гріха.","Але раб не перебуває в домі вічно, а Син перебуває вічно.","Отже, якщо Син визволить вас, то справді будете вільними.","Знаю, що ви рід Авраамів, однак шукаєте, як вбити Мене, бо слово Моє не вміщається у вас.","Я говорю те, що бачив у Отця Мого; і ви робите те, що бачили в отця вашого.","Сказали Йому у відповідь: отець наш є Авраам. Ісус сказав їм: якби ви були дітьми Авраама, то чинили б діла Авраамові.","Нині ж шукаєте, як вбити Мене, Чоловіка, Який сповістив вам правду, почуту від Бога; Авраам цього не робив.","Ви робите діла отця вашого. На це сказали Йому: ми не від любодійства народжені; маємо одного Отця — Бога.","Ісус сказав їм: якби Бог був Отець ваш, то ви любили б Мене, тому що Я вийшов і прийшов від Бога; бо Я не Сам від Себе прийшов, а Він послав Мене.","Чому ви не розумієте Моїх слів? Тому що не можете чути слова Мого.","Ваш батько є диявол; і ви хочете виконувати похоті батька вашого. Він людиновбивцею був споконвіку і не стоїть в істині, бо істини немає в ньому. Коли він говорить неправду, від себе говорить, бо він неправдомовець і батько неправди.","А коли Я істину говорю, то не вірите Мені.","Хто з вас викриє Мене у гріху? Якщо ж Я говорю істину, то чому ви не вірите Мені?","Хто від Бога, той слова Божі слухає; ви тому не слухаєте, що ви не від Бога.","На це юдеї сказали Йому у відповідь: чи не правду ми говоримо, що Ти самарянин і що біс у Тобі?","Ісус відповів: у Мені біса нема, але Я шаную Отця Мого, а ви зневажаєте Мене.","А втім, Я не шукаю слави Моєї; є Той, Хто шукає і судить.","Істинно, істинно кажу вам: хто слово Моє збереже, той не побачить смерти повік.","Юдеї сказали Йому: тепер ми зрозуміли, що біс у Тобі. Авраам і пророки померли, а Ти кажеш, що хто слово Моє збереже, той не зазнає смерти повік.","Невже Ти більший від отця нашого Авраама, який помер?","Ісус відповів: якщо Я Сам Себе славлю, то слава Моя ніщо. Мене прославляє Отець Мій, про Якого ви говорите, що Він Бог ваш.","І ви не пізнали Його, а Я знаю Його; і якщо скажу, що не знаю Його, то буду подібним до вас неправдомовцем. Але Я знаю Його і слово Його зберігаю.","Авраам, отець ваш, був би радий побачити день Мій; і побачив, і зрадів.","На це сказали Йому юдеї: Тобі немає ще й п’ятдесяти років, і Ти бачив Авраама?","Ісус сказав їм: істинно, істинно кажу вам: раніш, ніж був Авраам, Я є.","Тоді взяли каміння, щоб кинути на Нього; але Ісус сховався і вийшов з храму, пройшовши посеред них, і пішов далі."],"x":{"5":"2.20.10|4.22.22","12":"53.1.5|53.9.5|58.1.5","17":"4.19.15|4.17.6|50.18.16|64.13.1|75.10.28","18":"31.42.1|53.5.32","21":"53.13.33","23":"53.3.31|68.3.1","28":"53.7.16|53.12.32","32":"31.42.7|31.61.1|62.6.14","34":"57.2.19|62.6.16","35":"0.21.10","39":"62.4.16","44":"58.3.8","47":"53.10.27|58.4.6","54":"53.16.14|54.3.13","56":"0.15.6|0.22.16"}},{"v":["І, проходячи, побачив чоловіка, сліпого від народження.","Ученики Його запитали в Нього: Учителю, хто згрішив, — він чи батьки його, що сліпим народився?","Ісус відповів: ні він не згрішив, ні батьки його, а це для того, щоб відкрилися на ньому діла Божі.","Мені належить робити діла Того, Хто послав Мене, доки день є; прийде ніч, коли ніхто робити не зможе.","Доки Я в світі, Я Світло для світу.","Сказавши це, плюнув на землю, зробив із слини суміш і помазав сумішшю очі сліпому.","І сказав йому: іди, вмийся у купальні Силоам, що означає: посланий. Він пішов і вмився, і прийшов зрячим.","Сусіди і ті, що бачили його раніше, як він був сліпим, говорили: чи не той це, що сидів і просив?","Одні говорили, що це той; інші ж — що схожий на нього. Він же сказав: це я.","Тоді запитали в нього: як відкрилися в тебе очі?","Він казав їм у відповідь: Чоловік, Якого звуть Ісус, зробив суміш, помазав очі мої і сказав мені: іди в купальню Силоам і вмийся. Я пішов, умився і прозрів.","Тоді сказали йому: де ж Він? Він відповів: не знаю.","Повели цього колишнього сліпця до фарисеїв.","А була субота, коли Ісус зробив суміш і відкрив йому очі.","Спитали його також фарисеї, як він прозрів. Він же сказав їм: суміш поклав Він на мої очі, і я вмився і бачу.","Тоді деякі з фарисеїв говорили: Чоловік Цей не від Бога, бо не шанує суботи. Інші говорили: як може грішний чоловік такі чудеса творити? І сталася між ними суперечка.","Знов говорять сліпому: що ти скажеш про Того, Хто відкрив тобі очі? Він сказав: це пророк.","Але юдеї не повірили, що він був сліпим і прозрів, доки не покликали батьків того, хто прозрів,","і запитали, кажучи: чи це син ваш, про якого ви кажете, що народився сліпим? Як же він тепер бачить?","Батьки його сказали їм у відповідь: ми знаємо, що він — це син наш і що він сліпим народився,","а як тепер бачить, не знаємо, і хто відкрив йому очі, ми не знаємо. Він сам уже дорослий; самого спитайте, нехай сам про себе скаже.","Так відповіли батьки його, тому що боялись юдеїв; бо юдеї вже змовилися, щоб того, хто визнає Його за Христа, відлучити від синагоги.","Тому-то батьки його сказали: він уже дорослий, самого запитайте.","Отже, вдруге покликали чоловіка, який був сліпим, і сказали йому: віддай славу Богові; ми знаємо, що Чоловік Той — грішник.","Він сказав їм у відповідь: чи Він — грішник, не знаю; одне знаю, що я був сліпий, а тепер бачу.","Знову запитали його: що Він зробив з тобою? Як відкрив твої очі?","Відповів їм: я вже сказав вам, і ви не вислухали; що ще хочете почути? Чи не хочете і ви стати Його учениками?","Вони ж докорили йому і сказали: ти Його ученик, ми ж Мойсеєві учні.","Ми знаємо, що з Мойсеєм говорив Бог; а про Цього ж не знаємо, звідки Він.","Чоловік, який прозрів, сказав їм у відповідь: це й дивно, що ви не знаєте, звідки Він, а Він відкрив мені очі.","Але ми знаємо, що грішників Бог не слухає; хто шанує Бога і волю Його творить, того слухає.","Споконвіку не чувано, щоб хтось відкрив очі сліпому від народження.","Якби Він не був від Бога, то не міг би нічого творити.","Сказали йому у відповідь: у гріхах ти весь народився, і чи ти нас учиш? І вигнали його геть.","Ісус, почувши, що вигнали його геть, знайшов його і сказав йому: чи віруєш ти в Сина Божого?","Він відповів і сказав: а хто Він, Господи, щоб мені вірувати в Нього?","Ісус сказав йому: і бачив ти Його, і Він говорить з тобою.","Він же промовив: вірую, Господи! І поклонився Йому.","І сказав Ісус: на суд Я прийшов у світ цей, щоб незрячі бачили, а зрячі стали сліпими.","Почувши це, деякі з фарисеїв, що були з Ним, сказали Йому: невже і ми сліпі?","Ісус сказав їм: якби ви були сліпі, то не мали б на собі гріха, але як ви говорите, що бачите, то гріх лишається на вас."],"x":{"4":"53.4.34|53.12.35","5":"31.42.6|53.1.5|53.8.12","6":"53.11.37","7":"17.3.15","16":"53.7.43","17":"52.7.16|53.4.19","22":"53.12.42","29":"1.3.6","31":"26.15.29|31.1.15|43.3.4","32":"31.42.7","39":"50.11.25|64.3.14","41":"53.15.22"}},{"v":["Істинно, істинно кажу вам: хто входить в овечий двір не дверима, а десь перелазить, той злодій і розбійник.","А хто входить у двері, той пастир овець.","Йому воротар відчиняє, і вівці голос його чують, він кличе своїх овець на ймення і виводить їх.","І коли виведе своїх овець, йде поперед них, а вівці йдуть за ним, бо знають його голос.","За чужим же не йдуть, а тікають від нього, бо не знають чужого голосу.","Цю притчу сказав їм Ісус; але вони не зрозуміли, про що Він говорив їм.","Отже, знову сказав їм Ісус: істинно, істинно кажу вам, що Я двері вівцям.","Всі, скільки їх приходило переді Мною, є злодії й розбійники; але вівці не послухали їх.","Я є двері: хто через Мене увійде, той спасеться, і увійде, і вийде, і пасовище знайде.","Злодій приходить тільки для того, щоб украсти, вбити й погубити. Я прийшов для того, щоб мали життя, і надто мали.","Я Пастир Добрий: пастир добрий душу свою покладає за овець.","А наймит, не пастир, якому вівці не свої, побачивши, що йде вовк, кидає овець і тікає, а вовк хапає і розганяє овець.","А наймит тікає, бо він наймит, і не турбується про овець.","Я ж Пастир Добрий; і знаю Моїх, і знають Мене Мої.","Як знає Мене Отець, так і Я знаю Отця; і душу Мою покладаю за овець.","Й інших овець маю, які не з цього двору, і тих Мені треба привести; і голос Мій почують, і буде одне стадо і один Пастир.","Тому любить Мене Отець, що Я душу Мою віддаю, щоб знову прийняти її.","Ніхто не відбирає її від Мене, але Я Сам віддаю її. Маю владу віддати її і владу маю знову прийняти її. Цю заповідь Я прийняв від Отця Мого.","Через ці слова знову виникла суперечка між юдеями.","Багато з них говорили: Він біса має і безумствує; чому ж слухаєте Його?","Інші говорили: це слова не біснуватого; хіба може біс відкривати очі сліпим?","Було тоді в Єрусалимі свято оновлення, і стояла зима.","Ісус ходив у храмі, у притворі Соломоновім.","Тут юдеї обступили Його і говорили Йому: чи довго триматимеш душі наші у невіданні? Якщо Ти Христос, скажи нам прямо.","Ісус відповів їм: Я сказав вам, і не вірите; діла, які Я творю в ім’я Отця Мого, свідчать про Мене.","Але ви не вірите, бо ви не з Моїх овець, як Я сказав вам.","Вівці Мої голосу Мого слухаються, і Я знаю їх; і вони йдуть за Мною.","І Я дам їм життя вічне, і не загинуть повік; і ніхто не викраде їх з руки Моєї.","Отець Мій, Який дав Мені їх, більший за всіх, і ніхто не може викрасти їх з руки Отця Мого.","Я і Отець — єдине.","Тут знов юдеї схопили каміння, щоб побити Його.","Ісус відповів їм: багато добрих діл показав Я вам від Отця Мого; за яке з них хочете побити Мене камінням?","Юдеї сказали Йому у відповідь: не за добрі діла хочемо побити Тебе камінням, а за богохульство і за те, що Ти, будучи людиною, робиш Себе Богом.","Ісус відповів їм: чи не написано в законі вашому: Я сказав, що ви боги?","Якщо назвав богами тих, до кого було слово Боже, і не може порушитись Писання, —","чи Тому, Якого Отець освятив і послав у світ, ви говорите, що богохульствує, бо сказав: Я Син Божий?","Якщо Я не творю діл Отця Мого, не вірте Мені;","а якщо творю, то, коли не вірите Мені, вірте ділам Моїм, щоб пізнати і повірити, що Отець в Мені і Я в Ньому.","Тоді знову намагалися Його схопити; але Він ухилився від рук їхніх.","І пішов знову на той бік Йордану, на те місце, де раніше хрестив Іоан, і залишився там.","І багато прийшло до Нього і говорили, що Іоан не створив жодного чуда, але все, що Іоан сказав про Нього, було правдою.","І багато хто там увірував у Нього."],"x":{"8":"32.23.1|32.50.6|36.34.2","9":"25.22.2","11":"25.22.1|31.40.11|36.34.13|36.37.24|56.2.25","14":"36.34.11|72.2.19","16":"36.37.22","17":"31.53.11","18":"53.2.19|53.14.31","20":"51.3.21|53.7.20","22":"21.4.59","25":"53.5.36","26":"53.8.19|58.4.6","29":"4.33.3","31":"53.5.18","34":"25.81.6","36":"53.6.27","38":"53.14.10|53.17.21","40":"53.1.28","41":"53.5.33"}},{"v":["Був один недужий — Лазар з Вифанії, села Марії та її сестри Марфи.","Марія ж, брат якої Лазар був недужий, була та, що помазала Господа миром і обтерла ноги Його волоссям своїм.","Сестри послали сказати Йому: Господи, ось, кого Ти любиш, нездужає.","Ісус, почувши те, сказав: ця недуга не на смерть, а на славу Божу, щоб через неї прославився Син Божий.","Ісус же любив Марфу і сестру її та Лазаря.","Коли ж почув, що він хворий, то пробув два дні на тому місці, де знаходився.","Після цього сказав ученикам: підемо знову до Юдеї.","Ученики сказали Йому: Учителю, чи давно юдеї намагалися побити Тебе камінням, і Ти знову йдеш туди?","Ісус відповів: чи не дванадцять годин є у дні? Хто ходить удень, той не спотикається, тому що бачить світло світу цього;","а хто ходить уночі, спотикається, бо немає світла з ним.","Сказавши це, говорить їм потім: Лазар, друг наш, заснув; але Я йду розбудити його.","Ученики Його сказали: Господи, якщо заснув, то одужає.","Ісус говорив про смерть його, а вони думали, що Він говорить про звичайний сон.","Тоді Ісус сказав їм просто: Лазар помер;","і радію за вас, що Я не був там, щоб ви увірували; але ходімо до нього.","Тоді Фома, званий ще Близнюком, сказав ученикам: ходімо й ми і помремо з Ним.","Прийшовши, Ісус знайшов, що він уже чотири дні у гробі.","Вифанія ж була поблизу Єрусалима, стадій з п’ятнадцять.","І багато юдеїв прийшли до Марфи й Марії, щоб утішити їх у скорботі за братом їхнім.","Марфа, почувши, що йде Ісус, вийшла назустріч Йому; Марія ж сиділа вдома.","Тоді Марфа сказала Ісусові: Господи! Якби Ти був тут, не помер би брат мій.","Але й тепер знаю, що, коли чого Ти попросиш у Бога, дасть Тобі Бог.","Ісус говорить їй: воскресне брат твій.","Марфа сказала Йому: знаю, що воскресне при воскресінні, в останній день.","Ісус сказав їй: Я є воскресіння і життя; хто вірує в Мене, якщо і помре, оживе.","І кожен, хто живе і вірує в Мене, не помре повік. Чи віриш цьому?","Вона говорить Йому: так, Господи! Я вірую, що Ти Христос, Син Божий, Який гряде у світ.","Сказавши так, пішла і покликала Марію, сестру свою, нишком, кажучи: Учитель тут і кличе тебе.","Вона, як тільки почула, поспішно встала і пішла до Нього.","Ісус ще не входив у село, але був на тому місці, де зустріла Його Марфа.","Юдеї, які були з нею в домі і втішали її, коли побачили, що Марія поспішно встала і вийшла, пішли за нею, гадаючи, що вона пішла до гробу — плакати там.","Марія ж, прийшовши туди, де був Ісус, та побачивши Його, впала до ніг Його і сказала Йому: Господи! Якби Ти був тут, не помер би брат мій.","Ісус, коли побачив, що вона плаче і плачуть юдеї, які прийшли з нею, Сам уболівав духом і зворушився.","І сказав: де ви поклали його? Кажуть Йому: Господи, піди і подивись.","Заплакав Ісус.","Тоді юдеї говорили: дивись, як Він любив його.","А деякі з них сказали: чи не міг би Цей, що відкрив очі сліпому, зробити так, щоб і цей не помер?","Ісус же, знову пройнявшись жалем, приходить до гробу. То була печера, і камінь лежав на ній.","Ісус говорить: візьміть камінь. Сестра померлого, Марфа, говорить Йому: Господи! Вже смердить, бо чотири дні, як він у гробі.","Ісус говорить їй: чи не сказав Я тобі, що, коли будеш вірувати, побачиш славу Божу?","Відвалили камінь від печери, де лежав померлий. Ісус звів очі до неба і сказав: Отче! Хвалу Тобі воздаю, що Ти почув Мене.","Я і знав, що Ти завжди почуєш Мене; але сказав це для народу, який стоїть тут, щоб повірили, що Ти послав Мене.","Сказавши це, Він голосно промовив: Лазарю! Вийди геть.","І вийшов померлий, оповитий по руках і ногах поховальними пеленами, і обличчя його обв’язане було хусткою. Ісус говорить їм: розв’яжіть його, нехай іде.","Тоді багато з юдеїв, які прийшли до Марії і бачили, що сотворив Ісус, увірували в Нього.","А деякі з них пішли до фарисеїв і сказали їм, що зробив Ісус.","Тоді первосвященики й фарисеї зібрали раду і говорили: що нам робити? Цей Чоловік багато чудес творить.","Якщо залишимо Його так, то всі увірують у Нього, і прийдуть римляни і заволодіють містом нашим і народом.","Один же з них, на ім’я Каяфа, який був того року первосвящеником, сказав їм: ви нічого не знаєте,","і не подумаєте, що краще нам, щоб один чоловік помер за людей, ніж щоб увесь народ загинув.","Це ж сказав він не від себе, а, будучи того року первосвящеником, пророкував, що Ісус мав померти за народ, —","і не тільки за народ, але щоб і розсіяні чада Божі зібрати воєдино.","З того дня змовились убити Його.","І тому Ісус уже не ходив між юдеями явно, а пішов звідти в країну поблизу пустелі, в місто, що зветься Єфрем, і там залишився з учениками Своїми.","Наближалася Пасха юдейська, і багато людей з усієї країни прийшло до Єрусалима перед Пасхою, щоб очиститися.","Тоді шукали Ісуса і, стоячи в храмі, говорили один одному: як вам здається? Чи не прийде Він на свято?","А первосвященики і фарисеї дали наказ, що, коли хто довідається, де Він буде, нехай повідомить, щоб їм схопити Його."],"x":{"2":"50.26.7|51.14.3|53.12.3","4":"53.9.3","8":"53.10.31","9":"53.9.4","10":"53.12.35","24":"24.19.25-26|31.26.19|36.37.4|37.12.2","26":"53.6.54","27":"50.16.16","37":"53.9.6","47":"50.26.3|51.14.1","50":"53.18.14","52":"53.10.16|66.2.13","53":"50.21.38","55":"13.30.17"}},{"v":["Ісус же за шість днів до Пасхи прийшов у Вифанію, де був Лазар померлий, якого Він воскресив з мертвих.","Там приготували Йому вечерю, і Марфа прислуговувала, а Лазар був одним з тих, що возлежали з Ним.","Марія ж, узявши літр нардового чистого дорогоцінного мира, помазала ноги Ісуса і обтерла волоссям своїм ноги Його; і дім наповнився пахощами мира.","Тоді один з учеників Його, Іуда Симонів Іскаріот, який хотів видати Його, сказав:","а чому б було не продати це миро за триста динаріїв і не роздати убогим?","Сказав же він це не тому, що піклувався про убогих, а тому, що був злодієм. Він мав при собі грошову скриньку і носив, що туди вкидали.","Ісус же сказав: залиште її; вона зберегла це на день погребіння Мого.","Бо вбогих завжди маєте з собою, а Мене не завжди.","Багато юдеїв дізналися, що Він там, і прийшли не тільки заради Ісуса, але щоб бачити і Лазаря, якого Він воскресив з мертвих.","Первосвященики ж змовились убити і Лазаря,","бо через нього багато хто відходив від юдеїв і вірував в Ісуса.","На другий день багато народу прийшло на свято; почувши, що Ісус іде в Єрусалим,","взяли пальмове віття, вийшли назустріч Йому і викликували: осанна! Благословен, Хто йде в ім’я Господнє, Цар Ізраїлів!","Ісус же, знайшовши осля, сів на нього, як написано:","не бійся, дочко Сионська! Ось Цар твій гряде, сидячи на молодому ослі.","Ученики Його спочатку не зрозуміли цього, але коли прославився Ісус, тоді згадали, що так було про Нього написано, і це зробили Йому.","Народ, що був з Ним раніш, свідчив, що Він викликав Лазаря із гробу і воскресив його з мертвих.","Тому і зустрів Його народ, бо чув, що Він сотворив це чудо.","Фарисеї ж говорили між собою: чи бачите, що нічого не вдієте? Весь світ іде за Ним.","Між тими, що прийшли поклонитися на свято, деякі були еллінами.","Вони підійшли до Филипа, що був з Вифсаїди галилейської, і просили його, кажучи: господарю, хочемо бачити Ісуса.","Филип іде і говорить про те Андрієві; а потім Андрій і Филип розповідають про те Ісусові.","Ісус же сказав їм у відповідь: настав час прославитися Синові Людському.","Істинно, істинно кажу вам: якщо пшеничне зерно, упавши на землю, не помре, то залишиться одне, а якщо помре, то принесе багато плодів.","Хто любить душу свою, погубить її, а хто ненавидить душу свою у світі цьому, збереже її в життя вічне.","Хто Мені служить, нехай за Мною йде; і де Я, там і слуга Мій буде. І хто Мені служить, того вшанує Отець Мій.","Нині душа Моя стривожена; і що Мені сказати? Отче, спаси Мене від цієї години! Але задля цього Я і прийшов — на цю годину.","Отче, прослав ім’я Твоє! Тоді зійшов голос з неба: і прославив, і ще прославлю.","Народ, який стояв і чув те, говорив: це грім. А інші казали: ангел говорив Йому.","Ісус на це сказав: не для Мене був голос цей, а для народу.","Нині суд світові цьому; нині князь світу цього вигнаний буде геть.","І коли Я буду піднесений від землі, то всіх приверну до Себе.","Це говорив Він, даючи зрозуміти, якою смертю Він помре.","Народ відповів Йому: ми чули із закону, що Христос перебуває повік; як же Ти говориш, що належить піднестися Синові Людському? Хто є Цей Син Людський?","Тоді Ісус сказав їм: ще короткий час світло є з вами. Ходіть, поки є світло, щоб темрява вас не огорнула; а той, що ходить у темряві, не знає, куди йде.","Доки світло з вами, віруйте у світло, щоб бути вам синами світла. Це промовивши, Ісус відійшов від них і зник.","Стільки чудес сотворив Він перед ними, і вони не вірували в Нього,","щоб справдилося слово пророка Ісаї, який сказав: Господи! Хто повірив тому, що ми чули? І кому відкрилася сила Господня?","Тому не могли вони вірувати, що, як ще сказав Ісая:","засліпив очі їхні, закам’янив серця їхні, щоб не бачили очима і не розуміли серцем і не навернулися, щоб Я зцілив їх.","Це сказав Ісая, коли бачив славу Його і говорив про Нього.","Проте і з начальників багато хто увірував у Нього; та через фарисеїв не признавалися, щоб не відлучили їх від синагоги.","Бо полюбили більше людську славу, ніж славу Божу.","Ісус же проголосив: хто вірує в Мене, не в Мене вірує, а в Того, Хто послав Мене.","І хто Мене бачить, той бачить Того, Хто послав Мене.","Я Світло, прийшов у світ, щоб усякий, хто в Мене вірує, не залишався у темряві.","І коли хто почує слова Мої і не повірить, Я не суджу його, бо Я прийшов не судити світ, але спасти світ.","Хто від Мене відмовляється і не приймає слів Моїх, має собі суддю: слово, яке Я сказав, — воно судитиме його в останній день.","Бо Я говорив не від Себе; а Отець, Який послав Мене, Він дав Мені заповідь, що маю сказати і що говорити.","І Я знаю, що заповідь Його є життя вічне. Отже, що Я говорю, то говорю так, як сказав Мені Отець."],"x":{"1":"50.26.6|51.14.3|53.11.2","2":"52.10.40","6":"53.13.29","8":"4.15.11","13":"50.21.8|51.11.8|52.19.36","15":"48.9.9|31.62.11|50.21.5","25":"50.10.39|51.8.35|52.9.24|52.14.27","26":"53.17.24","27":"50.26.38|75.5.7","31":"53.14.30|53.16.11","32":"53.3.14","34":"9.7.13|25.88.37|31.9.7|36.37.25|37.2.44|37.7.14|43.5.2|52.1.33","38":"31.53.1|62.10.16","40":"31.6.9-10|50.13.14|51.4.12|52.8.10|54.28.26|62.11.8","43":"53.5.44","46":"53.3.19","47":"53.3.17","48":"51.16.16","49":"53.14.10"}},{"v":["Перед святом Пасхи Ісус, знаючи, що прийшов Його час перейти з цього світу до Отця, показав на ділі, що, полюбивши Своїх, які були в світі, до кінця полюбив їх.","І під час вечері, коли диявол уже вклав у серце Іуді Симоновому Іскаріотові видати Його,","Ісус, знаючи, що Отець усе віддав до рук Його і що Він від Бога вийшов і до Бога відходить,","встав від вечері, зняв з Себе верхній одяг і, взявши рушник, підперезався.","Потім налив води в умивальницю і почав умивати ноги ученикам, і обтирати рушником, яким був підперезаний.","Підходить і до Симона-Петра, а той говорить Йому: Господи! Чи Тобі умивати мої ноги?","Ісус сказав йому у відповідь: що Я роблю, ти тепер не знаєш, а зрозумієш потім.","Петро каже Йому: не вмиєш ніг моїх повік. Ісус відповів йому: якщо не вмию тебе, не матимеш частини зі Мною.","Симон-Петро каже Йому: Господи, не тільки ноги мої, але й руки і голову.","Ісус говорить йому: вмитому треба тільки ноги обмити, бо увесь чистий; і ви чисті, але не всі.","Бо знав Він зрадника Свого, тому і сказав, що не всі вони чисті.","Коли ж умив їм ноги і надів одяг Свій, то знову возліг і сказав їм: чи знаєте, що Я зробив вам?","Ви називаєте Мене Учителем і Господом, і добре кажете, бо Я Той і є.","Отже, якщо Я, Господь і Учитель, умив вам ноги, то і ви повинні вмивати ноги один одному.","Бо Я дав вам приклад, щоб і ви робили так само, як Я зробив вам.","Істинно, істинно кажу вам: раб не більший за господаря свого, і посланець не більший за того, хто послав його.","Якщо це знаєте, блаженні ви, коли виконуєте.","Не про всіх вас кажу; Я знаю тих, кого обрав. Але нехай здійсниться Писання: той, хто їсть зі Мною хліб, підняв на Мене п’яту свою.","Тепер кажу вам, перш ніж те збудеться, щоб, як станеться, ви повірили, що це Я.","Істинно, істинно кажу вам: хто приймає того, кого Я пошлю, Мене приймає; а хто Мене приймає, приймає Того, Хто послав Мене.","Сказавши це, Ісус стривожився духом, і засвідчив, і сказав: істинно, істинно кажу вам, що один з вас видасть Мене.","Тоді ученики озирались один на одного, не розуміючи, про кого Він говорить.","Один же з учеників Його, якого любив Ісус, возлежав при лоні Ісусовому.","Йому Симон-Петро зробив знак, щоб запитав, хто це, про кого Він говорить.","Той, припавши до грудей Ісуса, сказав Йому: Господи, хто це?","Ісус відповів: той, кому Я, вмочивши, подам хліб. І, вмочивши хліб, подав Іуді Симоновому Іскаріоту.","І з цим хлібом увійшов у нього сатана. І сказав йому Ісус: що робиш, роби швидше.","Але ніхто з тих, що возлежали, не зрозумів, до чого Він це сказав йому.","Оскільки в Іуди була грошова скринька, то деякі гадали, що Ісус звелів йому купити те, що треба було до свята, або щоб дав що-небудь убогим.","Він, взявши той хліб, одразу ж вийшов; а була ніч.","Коли він вийшов, Ісус промовив: нині прославився Син Людський, і Бог прославився в Ньому.","Якщо Бог прославився в Ньому, то і Бог прославить Його в Собі, і скоро прославить Його.","Діти! Недовго вже бути Мені з вами. Будете шукати Мене і, як Я сказав юдеям, — куди Я йду, ви не можете прийти, так і вам кажу тепер.","Заповідь нову даю вам: щоб ви любили один одного; як Я полюбив вас, так і ви любіть один одного.","З того знатимуть усі, що ви Мої ученики, якщо будете мати любов між собою.","Симон-Петро сказав Йому: Господи, куди Ти йдеш? Ісус відповів йому: куди Я йду, ти не можеш тепер іти за Мною, а згодом підеш за Мною.","Петро сказав Йому: Господи! Чому я не можу йти за Тобою тепер? Я душу мою покладу за Тебе.","Ісус відповів йому: душу твою за Мене покладеш? Істинно, істинно кажу тобі: не проспіває півень, як тричі зречешся Мене."],"x":{"1":"50.26.2|51.14.1","3":"50.11.27|50.28.18","10":"53.15.3","13":"63.8.6|67.2.11","16":"50.10.24|52.6.40|53.15.20","18":"25.40.10|54.1.16","19":"53.14.29","20":"50.10.40|52.10.16","21":"50.26.21|51.14.18|52.22.21","23":"53.21.20","31":"53.12.23","33":"53.7.34|53.8.21","34":"53.15.12|58.3.11|69.4.9","38":"50.26.34|51.14.30|52.22.34"}},{"v":["Нехай не тривожиться серце ваше; віруйте в Бога і в Мене віруйте.","В домі Отця Мого осель багато. А якби не так, Я сказав би вам: Я йду приготувати місце вам.","І коли піду і приготую вам місце, прийду знову і візьму вас до Себе, щоб і ви були там, де Я.","А куди Я йду, ви знаєте, і путь знаєте.","Фома сказав Йому: Господи! Не знаємо, куди йдеш; і як можемо знати путь?","Ісус сказав йому: Я є путь, і істина, і життя; ніхто не приходить до Отця, як тільки через Мене.","Коли б ви знали Мене, то знали б і Отця Мого. І віднині знаєте Його і бачили Його.","Филип сказав Йому: Господи, покажи нам Отця, і нам вистачить.","Ісус сказав йому: стільки часу Я з вами, і ти не знаєш Мене, Филипе? Хто бачив Мене, той і Отця бачив; як же ти говориш: покажи нам Отця?","Хіба ти не віриш, що Я в Отці і Отець у Мені? Слова, які Я кажу, не від Себе кажу; Отець, Який в Мені перебуває, Він творить діла.","Вірте Мені, що Я в Отці і Отець у Мені. Якщо ж ні, то вірте Мені за самими ділами.","Істинно, істинно кажу вам: хто вірує в Мене, діла, які творю Я, і він створить, і більше цих створить; тому що Я до Отця Мого іду.","І коли чого попросите у Отця в ім’я Моє, те зроблю, щоб Отець прославився в Сині.","І коли чого попросите в ім’я Моє, Я те зроблю.","Якщо любите Мене, то дотримуйтесь Моїх заповідей.","І Я ублагаю Отця, й іншого Утішителя дасть вам, щоб був з вами повік,","Духа істини, Якого світ не може прийняти, бо не бачить Його і не знає Його; ви ж знаєте Його, бо Він з вами перебуває і у вас буде.","Не залишу вас сиротами; прийду до вас.","Ще трохи, і світ уже не побачить Мене; а ви побачите Мене, бо Я живу, і ви будете жити.","Того дня дізнаєтесь ви, що Я в Отці Моєму, і ви в Мені, і Я в вас.","Хто має заповіді Мої і дотримується їх, той любить Мене; а хто любить Мене, того полюбить Отець Мій; і Я полюблю його і явлюся йому Сам.","Іуда, не Іскаріот, говорить Йому: Господи, що це, що Ти хочеш явити Себе нам, а не світові?","Ісус сказав йому у відповідь: хто любить Мене, той слово Моє збереже; і Отець Мій полюбить його, і Ми прийдемо до Нього і оселю сотворимо у Нього.","А хто не любить Мене, слів Моїх не береже; слово ж, яке ви чуєте, не Моє, а Отця, Який послав Мене.","Це сказав Я вам, перебуваючи з вами.","Утішитель же, Дух Святий, Якого пошле Отець в ім’я Моє, навчить вас усього і нагадає вам усе, що Я говорив вам.","Мир залишаю вам, мир Мій даю вам; не так, як світ дає, Я даю вам. Нехай не тривожиться серце ваше і нехай не страхається.","Ви чули, що Я сказав вам: іду від вас і прийду до вас. Коли б ви любили Мене, то зраділи б, що Я сказав: іду до Отця; бо Отець Мій більший за Мене.","І ось Я сказав вам про те, перш ніж збулося, щоб ви повірили, коли збудеться.","Вже небагато Мені говорити з вами; бо йде князь світу цього, і в Мені він не має нічого.","Та щоб світ знав, що Я люблю Отця і, як заповів Мені Отець, так і творю. Вставайте, підемо звідси."],"x":{"3":"53.17.24|69.4.17","6":"31.35.8|53.1.14:17|53.6.33:40|53.8.32|53.10.28|53.11.25|58.5.20|66.1.13","13":"50.7.7|51.11.24|52.11.9|53.15.7|53.16.23|55.1.6","17":"53.16.13|63.2.14","19":"53.11.25|69.4.14","23":"48.2.10|63.3.16|76.3.20","24":"53.12.49","26":"53.15.26","27":"67.4.7","30":"53.12.31|53.16.11","31":"53.10.18|75.10.7"}},{"v":["Я є істинна виноградна лоза, а Отець Мій — виноградар.","Всяку гілку в Мене Він відсікає, що не плодоносить, і всяку, що плодоносить, очищає, щоб більше принесла плоду.","Ви вже очищені через слово, яке Я проповідував вам.","Перебувайте в Мені, і Я у вас. Як гілка не може приносити плоду сама від себе, якщо не буде на лозі, так і ви, якщо не будете в Мені.","Я є лоза, а ви гілки; хто перебуває в Мені, і Я в ньому, той приносить багато плоду; бо без Мене не можете робити нічого.","Хто не буде в Мені, той буде відкинутий геть, як гілка, і всохне; а такі гілки збирають і кидають у вогонь, і вони згоряють.","Якщо перебуватимете в Мені, і слова Мої у вас будуть, то, чого б ви не захотіли, просіть, і буде вам.","Тим прославиться Отець Мій, якщо ви принесете багато плоду і будете Моїми учениками.","Як полюбив Мене Отець, так і Я полюбив вас; перебувайте ж у Моїй любові.","Якщо заповідей Моїх дотримаєтесь, то будете в любові Моїй, як і Я, дотримавшись заповідей Отця Мого, перебуваю в Його любові.","Це сказав Я вам, щоб радість Моя у вас перебувала, і радість ваша буде повна.","Це є заповідь Моя, щоб ви любили один одного, як Я полюбив вас.","Немає більше від тієї любови, як хто душу свою покладе за друзів своїх.","Ви — друзі Мої, якщо виконуєте те, що Я заповідаю вам.","Не називаю вас більше рабами, бо раб не знає, що робить господар його; а Я назвав вас друзями, тому що сказав вам усе, що чув від Отця Мого.","Не ви Мене обрали, але Я вас обрав і настановив вас, щоб ви йшли і приносили плід, і щоб плід ваш залишився, щоб, чого не попросите в Отця в ім’я Моє, Він дав вам.","Це заповідаю вам, щоб ви любили один одного.","Якщо світ вас ненавидить, знайте, що Мене перше, ніж вас, зненавидів.","Якби ви були від світу, то світ любив би своє; а оскільки ви не від світу, але Я обрав вас від світу, тому ненавидить вас світ.","Пам’ятайте слово, яке Я сказав вам: раб не більший за господаря свого. Якщо Мене гнали, то гнатимуть і вас; якщо Мого слова дотримувались, будуть дотримуватись і вашого.","Та все те чинитимуть вам за ім’я Моє, тому що не знають Того, Хто послав Мене.","Якби Я не прийшов і не говорив їм, то не мали б гріха; а тепер не мають виправдання за гріх свій.","Хто ненавидить Мене, той ненавидить і Отця Мого.","Коли б Я не творив серед них діл, яких ніхто інший не створив, то не мали б гріха; а тепер і бачили, і зненавиділи й Мене, і Отця Мого.","Але нехай справдиться слово, написане в законі їхньому: зненавиділи Мене даремно.","Коли ж прийде Утішитель, Якого Я пошлю вам від Отця, Дух істини, Який від Отця виходить, Він буде свідчити про Мене.","Також і ви будете свідчити, бо ви спочатку зі Мною."],"x":{"2":"50.15.13|65.5.22","3":"53.13.10|58.2.7","5":"54.4.12","6":"36.15.4|50.3.10|50.7.19","7":"53.14.13|53.16.23|58.3.22","12":"53.13.34|58.3.11|66.5.2|69.4.9","15":"66.1.9|66.3.5","16":"51.16.15","18":"58.3.13","20":"50.10.24|50.24.9|51.13.9|52.21.12|53.13.16","21":"53.16.3","25":"25.68.5|25.34.19","26":"52.24.49|53.14.26","27":"54.1.8|54.2.32|56.5.1"}},{"v":["Це сказав Я вам, щоб ви не спокусилися.","Виженуть вас із синагог; прийде навіть час, коли всякий, хто вбиватиме вас, буде думати, що тим він служить Богові.","Так будуть робити, бо не пізнали ні Отця, ні Мене.","Але Я сказав це для того, щоб ви, як прийде той час, згадали, що Я казав вам про те. А не говорив вам цього спочатку тому, що був з вами.","А тепер іду до Того, Хто Мене послав, і ніхто з вас не питає Мене: куди йдеш?","Але від того, що Я сказав вам це, скорботою пройнялися серця ваші.","Але Я істину кажу вам: краще для вас, щоб Я пішов. Бо, якщо Я не піду, Утішитель не прийде до вас; а як піду, то пошлю Його до вас,","і коли Він прийде, викриє світ за гріх, і за правду, і за суд.","За гріх — тому, що не вірують в Мене.","За правду — тому, що Я йду до Отця Мого, і вже не побачите Мене.","А за суд, бо князя світу цього осуджено.","Ще багато чого маю сказати вам, але ви тепер не можете вмістити.","Коли ж прийде Він, Дух істини, то наставить вас на всяку істину; бо не від Себе говоритиме, а буде говорити те, що почує, і майбутнє звістить вам.","Він прославить Мене, бо від Мого візьме і звістить вам.","Усе, що має Отець, — Моє; тому Я сказав, що від Мого візьме і звістить вам.","Ще трохи, і ви вже не побачите Мене, і знову незабаром побачите Мене, бо Я йду до Отця.","Тут деякі з учеників Його сказали один одному: що це Він говорить нам: ще трохи, і ви не побачите Мене, і знову незабаром побачите Мене; і: Я йду до Отця?","Отже, вони говорили: що це говорить Він: ще трохи? Не знаємо, що каже.","Ісус, зрозумівши, що хочуть спитати Його, сказав їм: чи про те допитуєтеся між собою, що Я сказав: ще трохи, і не побачите Мене, і знову незабаром побачите Мене?","Істинно, істинно кажу вам: ви будете плакати і ридати, а світ зрадіє; ви печальні будете, та печаль ваша за радість буде.","Жінка, коли родить, терпить скорботу, бо прийшла година її; коли ж породила дитя, вже не пам’ятає скорботи від радости, тому що народилася людина на світ.","Так і ви маєте печаль нині; але Я знову побачу вас, і зрадіє серце ваше, і радости вашої ніхто не відбере від вас.","І в той день ви не спитаєте Мене ні про що. Істинно, істинно кажу вам: чого б ви не попросили в Отця в ім’я Моє, дасть вам.","Донині ви нічого не просили в ім’я Моє; просіть і одержите, щоб радість ваша була повною.","Це Я говорив вам притчами; але настає час, коли вже не буду говорити вам притчами, а відкрито сповіщу вам про Отця.","В той день будете просити в ім’я Моє, і не кажу вам, що Я благатиму Отця за вас:","бо Сам Отець любить вас, тому що ви полюбили Мене і увірували, що Я зійшов від Бога.","Я зійшов від Отця і прийшов у світ; і знову залишаю світ і йду до Отця.","Ученики Його сказали Йому: ось тепер Ти говориш просто, і притчі не кажеш ніякої.","Тепер бачимо, що Ти все знаєш і не потребуєш, щоб хто питав Тебе. Тому і віруємо, що Ти від Бога зійшов.","Ісус відповів їм: тепер віруєте?","Ось настає час, і вже настав, коли ви розійдетесь кожний до свого і Мене залишите одного, але Я не один, бо Отець зі Мною.","Це сказав Я вам, щоб ви мали в Мені мир. У світі зазнаєте скорботи, але мужайтесь: Я переміг світ."],"x":{"3":"53.15.21","4":"50.9.15|53.14.29","5":"53.7.33","7":"53.15.26","11":"53.12.31|53.14.30|68.2.15","13":"50.10.19","15":"53.17.10","22":"52.24.41:52|53.20.20|56.1.8","23":"50.7.7|51.11.24|52.11.9|53.14.13|53.15.7|55.1.6","26":"62.8.34","27":"53.17.25","32":"50.26.31|51.14.27","33":"58.4.4|63.15.57"}},{"v":["Після цих слів Ісус звів очі Свої до неба і сказав: Отче! Прийшов час. Прослав Сина Твого, щоб і Син Твій прославив Тебе;","як Ти дав Йому владу над усякою плоттю, щоб усьому, що Ти дав Йому, дав Він життя вічне.","Це ж є життя вічне, щоб пізнали Тебе, Єдиного Істинного Бога, і Того, Кого Ти послав, Ісуса Христа.","Я прославив Тебе на землі, звершив діло, яке Ти доручив Мені виконати.","І нині прослав Мене Ти, Отче, в Тебе Самого — славою, яку Я мав у Тебе, коли ще не було світу.","Я явив ім’я Твоє людям, яких Ти дав Мені від світу; вони були Твої, і Ти дав їх Мені, і вони зберегли слово Твоє.","Нині зрозуміли, що все, що Ти дав Мені, є від Тебе.","Бо слова, які Ти дав Мені, Я передав їм, і вони прийняли і зрозуміли воістину, що Я зійшов від Тебе, і увірували, що Ти послав Мене.","Я за них благаю, — не за весь світ благаю, але за тих, яких Ти дав Мені, тому що вони Твої.","І все Моє — Твоє, і Твоє — Моє; і Я прославився в них.","Я вже не в світі, та вони в світі, а Я до Тебе йду. Отче Святий! Збережи їх в ім’я Твоє, тих, кого Ти дав Мені, щоб вони були єдине, як і Ми.","Коли Я був з ними у світі, Я зберігав їх в ім’я Твоє; тих, яких Ти дав Мені, Я зберіг, і ніхто з них не загинув, тільки син погибельний, щоб збулося Писання.","Нині ж до Тебе йду, і це говорю у світі, щоб вони мали в собі радість Мою повну.","Я дав їм слово Твоє, і світ зненавидів їх, тому що вони не від світу, як і Я не від світу.","Не благаю, щоб Ти взяв їх від світу, але щоб зберіг їх від зла.","Вони не від світу, як і Я не від світу.","Освяти їх істиною Твоєю; слово Твоє є істина.","Як Ти послав Мене у світ, так і Я послав їх у світ.","І за них Я освячую Себе, щоб і вони були освячені істиною.","Не за них же тільки благаю, але й за віруючих у Мене за словом їхнім.","Щоб усі були єдине: як Ти, Отче, в Мені, і Я в Тобі, так і вони нехай будуть в Нас єдине, — щоб увірував світ, що Ти послав Мене.","І славу, яку Ти дав Мені, Я дав їм: щоб були єдине, як і Ми єдине;","Я в них, і Ти в Мені; щоб вони були звершені в єдності, і щоб зрозумів світ, що Ти послав Мене і полюбив їх, як полюбив Мене.","Отче! Ті, кого Ти дав Мені, хочу, щоб там, де Я, і вони були зі Мною, щоб бачили славу Мою, яку Ти дав Мені, тому що полюбив Мене раніше від створення світу.","Отче Праведний! І світ Тебе не пізнав; а Я пізнав Тебе, і ці пізнали, що Ти послав Мене.","І Я відкрив їм ім’я Твоє і відкрию, щоб любов, якою Ти полюбив Мене, в них була, і Я в них."],"x":{"1":"53.12.23","2":"37.7.14|50.28.18|75.2.5-8","3":"53.6.29|58.3.23","5":"76.5.12","6":"53.18.9","8":"53.16.27","10":"53.16.15","11":"53.10.30|66.4.3","12":"25.108.17:8|53.18.9","14":"53.8.23","17":"25.118.142|53.14.6","18":"31.61.1","19":"75.9.14","21":"53.17.11","24":"53.12.26","26":"53.15.15"}},{"v":["Сказавши це, Ісус вийшов з учениками Своїми на той бік потоку Кедрону, де був сад, в який увійшов Сам і ученики Його.","Знав же це місце й Іуда, зрадник Його, тому що Ісус часто збирався там з учениками Своїми.","Отже, Іуда, взявши загін воїнів та слуг первосвящеників і фарисеїв, приходить туди з ліхтарями і світильниками та зброєю.","Ісус же, знаючи все, що з Ним буде, вийшов і сказав їм: кого шукаєте?","Йому відповіли: Ісуса Назорея. Ісус говорить їм: це Я. Стояв же з ними й Іуда, зрадник Його.","І коли сказав їм: це Я, — вони відступили назад і впали на землю.","Знову запитав їх Ісус: кого шукаєте? Вони сказали: Ісуса Назорея.","Ісус відповів: Я сказав вам, що це Я; отже, якщо Мене шукаєте, залиште цих, нехай ідуть.","Щоб збулося сказане слово: з тих, якого Ти дав Мені, Я не погубив нікого.","Симон же Петро, маючи меч, витяг його і вдарив раба первосвященика і відсік йому праве вухо. Ім’я раба було Малх.","Але Ісус сказав Петрові: сховай меч у піхви; невже Мені не пити чаші, яку дав Мені Отець?","Тоді воїни, і тисяцький, і слуги юдейські взяли Ісуса і зв’язали Його.","І відвели Його спершу до Анни, бо він був тестем Каяфи, який був первосвящеником того року.","Це був той Каяфа, який дав пораду юдеям, що краще одному чоловікові вмерти за народ.","Услід за Ісусом ішли Симон-Петро та інший ученик; ученик же той був знайомий первосвященикові і ввійшов з Ісусом у двір первосвященика.","А Петро стояв зовні при дверях. Потім ученик, який був знайомий первосвященикові, вийшов і сказав воротарці, і ввів Петра.","І ось рабиня-воротарка каже Петрові: чи ти не з учеників Цього Чоловіка? Він сказав: ні.","Тим часом раби і слуги, розпаливши вогнище, бо було холодно, стояли і грілися. Петро також стояв з ними і грівся.","Первосвященик же запитав Ісуса про учеників Його і про вчення Його.","Ісус відповів йому: Я говорив світові відкрито; Я завжди навчав у синагогах і в храмі, де завжди юдеї сходяться, і таємно не говорив нічого.","Чого запитуєш Мене? Запитай тих, які чули, що Я говорив їм; ось ці знають, що Я говорив.","Коли Він сказав це, один із слуг, що стояв близько, ударив Ісуса по щоці, кажучи: так відповідаєш Ти первосвященикові?","Ісус відповів йому: якщо Я сказав зле, то доведи, що зле, а коли добре, за що ти б’єш Мене?","Анна відіслав Його зв’язаного до первосвященика Каяфи.","А Симон-Петро стояв і грівся. Тут сказали йому: чи не з учеників Його і ти? Він відрікся і сказав: ні.","Один з рабів первосвященика, родич того, якому Петро відсік вухо, говорить: чи я не бачив тебе з Ним у саду?","Петро знову відрікся, і зараз же заспівав півень.","Від Каяфи повели Ісуса до преторії. Був ранок; і вони не ввійшли у преторію, щоб не осквернитися, але щоб можна було їсти паску.","Пилат вийшов до них і сказав: у чому ви звинувачуєте Чоловіка Цього?","Вони сказали йому у відповідь: якби Він не був злочинець, ми не видали б Його тобі.","Пилат сказав їм: візьміть Його ви, і за законом вашим судіть Його. Юдеї сказали йому: нам не дозволено віддавати на смерть нікого, —","щоб справдилося слово Ісусове, яке Він сказав, даючи зрозуміти, якою смертю мав померти.","Тоді Пилат знову ввійшов у преторію, покликав Ісуса і сказав Йому: чи не Ти Цар Юдейський?","Ісус відповів йому: чи від себе ти говориш це, чи інші сказали тобі про Мене?","Пилат відповів: хіба я юдей? Твій народ і первосвященики видали Тебе мені; що Ти зробив?","Ісус відповів: Царство Моє не від світу цього: якби від світу цього було Царство Моє, то слуги Мої змагалися б за Мене, щоб Я не був виданий юдеям; але нині Царство Моє не звідси.","Пилат сказав Йому: отже, Ти Цар? Ісус відповів: ти говориш, що Я Цар. Я для того народився і для того прийшов у світ, щоб свідчити про істину; кожен, хто від істини, слухається голосу Мого.","Пилат сказав Йому: що є істина? І, сказавши це, знову вийшов до юдеїв і сказав їм: я ніякої провини не знаходжу в Ньому.","Є ж у вас звичай, щоб я одного відпускав вам на Пасху; чи хочете, відпущу вам Царя Юдейського?","Тоді знову закричали всі, кажучи: не Його, а Варавву. Варавва ж був розбійник."],"x":{"1":"50.26.36","3":"50.26.47|51.14.43|52.22.47|54.1.16","9":"53.17.6:12","10":"50.26.51","13":"50.26.57|51.14.53|52.22.54","14":"53.11.50","17":"50.26.69|51.14.66|52.22.56","24":"50.26.57|51.14.53|52.22.54","28":"50.27.2|51.15.1|52.22.66","32":"50.20.19","33":"50.27.11|51.15.2|52.23.3","36":"37.2.44","37":"71.6.13","39":"50.27.15|51.15.6|52.23.17","40":"54.3.14"}},{"v":["Тоді Пилат узяв Ісуса і звелів бити Його.","І воїни, сплівши вінець з терну, поклали Йому на голову, і одягли Його в багряницю,","і говорили: радуйся, Царю Юдейський! І били Його по щоках.","Пилат знову вийшов і сказав їм: ось я виводжу Його до вас, щоб ви знали, що я не знаходжу в Ньому ніякої провини.","Тоді вийшов Ісус у терновому вінці і в багряниці. І сказав їм Пилат: це — Чоловік!","Коли ж побачили Його первосвященики і слуги, то закричали: розіпни, розіпни Його! Пилат говорить їм: візьміть Його ви, і розіпніть; бо я не знаходжу в Ньому провини.","Юдеї відповіли йому: ми маємо закон, і за законом нашим Він повинен умерти, тому що зробив Себе Сином Божим.","Пилат же, почувши це слово, ще більше злякався.","І знов увійшов у преторію і сказав Ісусові: звідки Ти? Але Ісус відповіді не дав йому.","Пилат же каже Йому: чи мені не відповідаєш? Хіба не знаєш, що я маю владу розіп’ясти Тебе, і владу маю відпустити Тебе?","Ісус відповів: ти не мав би наді Мною ніякої влади, якби не було тобі дано звище. Тому більший гріх на тому, хто видав Мене тобі.","З того часу Пилат намагався відпустити Його. Юдеї ж кричали: якщо відпустиш Його, ти не друг кесареві; всякий, хто робить себе царем, противиться кесареві.","Пилат, почувши це слово, вивів Ісуса і сів на судилищі, на місці, що зветься ліфостротон*, а по-єврейськи — гаввафа.","Тоді була п’ятниця перед Пасхою, близько шостої години. І сказав Пилат юдеям: це Цар ваш!","Вони ж закричали: візьми, візьми і розіпни Його! Пилат говорить їм: чи Царя вашого розіпну? Первосвященики відповіли: немає в нас царя, крім кесаря.","І тоді він видав Його їм на розп’яття. І взяли Ісуса, і повели.","І, несучи хрест Свій, Він вийшов на місце, що зветься Лобне, по-єврейськи Голгофа;","там розіп’яли Його, і з Ним двох інших, з одного і другого боку, а посередині Ісуса.","Пилат же написав і напис і виставив на хресті. Написано було: Ісус Назорей, Цар Юдейський.","Цей напис читало багато юдеїв, тому що місце, де був розіп’ятий Ісус, було недалеко від міста, і написано було єврейською, грецькою, римською мовами.","Первосвященики ж юдейські сказали Пилатові: не пиши: Цар Юдейський, але що Він говорив: Я Цар Юдейський.","Пилат відповів: що я написав — те написав.","Воїни ж, коли розіп’яли Ісуса, взяли одяг Його і розділили на чотири частини, кожному воїнові по частині, і хітон. Хітон же був не зшитий, а весь зітканий згори.","Вирішили між собою: не будемо роздирати його, а киньмо жереб на нього, кому буде, — щоб збулося сказане в Писанні: розділили ризи Мої між собою, за одяг Мій кидали жереб. Так воїни і зробили.","Біля хреста Ісуса стояли Мати Його і сестра Матері Його, Марія Клеопова, і Марія Магдалина.","Ісус, побачивши Матір і ученика, що тут стояв, якого любив, говорить до Матері Своєї: Жоно! Це — син Твій.","Потім каже ученикові: це — Мати твоя! І з цього часу ученик взяв Її до себе.","Після того Ісус, знаючи, що вже усе звершилося, щоб справдилося Писання, говорить: пити!","Стояла тут посудина, повна оцту. Воїни, намочивши оцтом губку і настромивши її на тростину, піднесли до уст Його.","Коли ж спробував оцту Ісус, сказав: звершилось! І, схиливши голову, віддав дух.","А оскільки тоді була п’ятниця, то юдеї, щоб не залишати тіл на хресті в суботу [бо та субота була Великдень], просили Пилата, щоб перебити їхні голінки і зняти їх.","Отже, прийшли воїни і в першого перебили голінки, і в другого, розіп’ятого з Ним.","А коли, підійшовши до Ісуса, побачили, що Він уже помер, то не перебили в Нього голінок.","Але один з воїнів списом проколов Йому ребра, і відразу витекли кров і вода.","І той, що бачив, засвідчив, — і свідчення його правдиве. Він знає, що говорить правду, щоб ви повірили.","Бо це сталося, щоб справдилося Писання: кість не розломиться в Нього.","Також і в іншому місці Писання говориться: будуть дивитися на Того, Якого прокололи.","Після цього Йосиф з Аримафеї, ученик Ісуса, але таємний — з остраху перед юдеями, просив Пилата, щоб зняти тіло Ісуса; і Пилат дозволив. Він пішов і зняв тіло Ісуса.","Прийшов також і Никодим, який приходив раніше до Ісуса вночі, і приніс суміш смирни та алое, близько сотні літрів.","Отже, вони взяли тіло Ісуса і обгорнули пеленами з пахощами, як за звичаєм поховання в юдеїв.","На тому місці, де Його розіп’яли, був сад, і в саду новий гріб, в якому ще ніхто ніколи не був покладений.","Там і поклали Ісуса ради п’ятниці юдейської, тому що гріб був близько."],"x":{"1":"50.27.26|51.15.15","4":"53.18.38|54.3.13","6":"50.27.23|51.15.14|52.23.4|54.13.28","7":"4.18.20","9":"31.53.7|53.18.33","11":"52.22.53","17":"50.27.33|51.15.22|52.23.33|75.13.12","23":"50.27.35|51.15.24|52.23.34","24":"25.21.19","25":"52.2.35","28":"25.68.22|50.27.48","31":"4.21.23","36":"1.12.46|3.9.12","37":"48.12.10|76.1.7","38":"50.27.57|51.15.43|52.23.50","39":"53.3.2|53.7.50"},"n":{"13":["Кам’яний поміст."]}},{"v":["У перший же день після суботи Марія Магдалина приходить до гробу вранці, коли було ще темно, і бачить, що камінь відвалений від гробу.","Отже, біжить і приходить до Симона-Петра та до іншого ученика, якого любив Ісус, і каже їм: узяли Господа з гробу і не знаємо, де поклали Його.","Негайно ж вийшли Петро та інший ученик і пішли до гробу.","Вони бігли обидва разом; але інший ученик біг швидше за Петра і прибув до гробу перший.","І, нахилившись, побачив, що лежать пелени; але не ввійшов.","Слідом за ним прийшов Симон-Петро, і ввійшов у гріб, і побачив одні лиш пелени, що лежали;","а хустина, яка була на голові Його, лежала згорнена не з пеленами, а осторонь, на іншому місці.","Тоді ввійшов і інший ученик, що раніше прийшов до гробу, і побачив, і увірував.","Бо вони ще не знали Писання, що Йому належало воскреснути з мертвих.","Тоді ученики знову повернулися до себе.","Марія стояла зовні біля гробу і плакала; і, коли плакала, нахилилася до гробу,","і бачить двох ангелів у білому, що сиділи — один в головах, а другий в ногах, де лежало тіло Ісусове.","І вони кажуть їй: жоно, чого плачеш? Говорить їм: взяли Господа мого, і не знаю, де поклали Його.","Сказавши це, обернулася назад і побачила Ісуса, Який стояв, але не впізнала, що це Ісус.","Говорить їй Ісус: жоно, чого плачеш? Кого шукаєш? Вона, думаючи, що це садівник, каже Йому: господарю, якщо ти забрав Його, скажи мені, де ти поклав Його, і я візьму Його.","Ісус говорить їй: Маріє! Вона, обернувшись, каже Йому: Раввуні! Що означає: Учителю!","Ісус говорить їй: не доторкайся до Мене, бо Я ще не зійшов до Отця Мого; а йди до братів Моїх і скажи їм: іду до Отця Мого і Отця вашого, і до Бога Мого і Бога вашого.","Марія Магдалина прийшла і сповістила ученикам, що бачила Господа і що Він це сказав їй.","Того ж першого дня після суботи, ввечері, коли двері дому, де зібралися ученики Його, були замкнені з остраху перед юдеями, прийшов Ісус і став посередині, і каже їм: мир вам!","Сказавши це, Він показав їм руки, і ноги, і ребра Свої. Ученики зраділи, побачивши Господа.","Ісус же сказав їм вдруге: мир вам! Як послав Мене Отець, так і Я посилаю вас.","Сказавши це, Він дихнув і говорить їм: прийміть Духа Святого.","Кому відпустите гріхи, тим відпустяться, на кому залишите, залишаться.","Фома ж, один з дванадцятьох, який звався Близнюком, не був тут з ними, коли приходив Ісус.","Інші ученики сказали йому: ми бачили Господа. Він же сказав їм: якщо не побачу на руках Його рани від цвяхів і не вкладу пальця мого в рани від цвяхів, і не вкладу руки моєї в ребра Його, не повірю.","Через вісім днів ученики Його знову були в домі, й Фома з ними. Прийшов Ісус, коли двері були замкнені, став посеред них і сказав: мир вам!","Потім говорить Фомі: дай палець твій сюди і подивись на руки Мої; подай руку твою і вклади в ребра Мої, і не будь невірним, але вірним.","Фома у відповідь сказав Йому: Господь мій і Бог мій!","Ісус говорить йому: ти повірив, тому що побачив Мене; блаженні ті, що не бачили й увірували.","Багато інших чудес сотворив Ісус перед учениками Своїми, про які не написано в цій книзі.","Це ж написано, щоб ви увірували, що Ісус є Христос, Син Божий, і, віруючи, мали життя в ім’я Його."],"x":{"1":"50.28.1|51.16.1|52.24.1","6":"52.24.12","9":"25.15.10|31.53.11|42.2.1","11":"50.28.1|51.16.5","14":"50.28.9|51.16.9","17":"25.21.23|50.28.10|62.8.29|75.2.11","19":"51.16.14|52.24.36|54.13.31|63.15.5:7","20":"53.16.22","21":"53.17.18","23":"50.16.19|50.18.18","25":"53.19.34","29":"56.1.8|64.5.7","30":"53.21.25","31":"53.3.15|62.15.4"}},{"v":["Після того знову явився Ісус ученикам Своїм по воскресінні з мертвих біля моря Тиверіадського. Явився ж так:","були разом Симон-Петро, і Фома, званий Близнюком, і Нафанаїл з Кани галилейської, і сини Зеведеєві, і двоє інших з учеників Його.","Симон-Петро говорить їм: йду ловити рибу. Кажуть йому: йдемо і ми з тобою! Пішли і відразу ввійшли в човен, і не впіймали в ту ніч нічого.","А коли вже настав ранок, Ісус стояв на березі; але ученики не впізнали, що це Ісус.","Ісус говорить їм: діти, чи є у вас яка їжа? Вони відповіли: ні.","Він же сказав їм: закиньте сіті з правого боку човна і впіймаєте. Вони закинули, і вже не могли витягти через велику кількість риби.","Тоді ученик, якого любив Ісус, говорить Петрові: це Господь. Симон же Петро, почувши, що це Господь, оперезався одягом, бо він був нагий, і кинувся в море.","А інші ученики припливли човном, бо недалеко були від землі, ліктів близько двохсот, і тягли сіть з рибою.","А коли вийшли на землю, бачать розкладене вогнище, і рибу, що на ньому лежала, і хліб.","Ісус говорить їм: принесіть тієї риби, яку ви тепер упіймали.","Симон-Петро пішов і витяг на землю сіть, повну великих рибин — сто п’ятдесят три; і від такої кількости риби не прорвалася сіть.","Ісус говорить їм: ідіть обідайте. Ніхто ж з учеників не посмів запитати Його: хто Ти? Бо знали, що це Господь.","Ісус підходить, бере хліб і дає їм, також і рибу.","Це вже втретє явився Ісус ученикам Своїм по воскресінні Своєму з мертвих.","Коли ж вони обідали, Ісус каже Симону-Петрові: Симоне Іонин! Чи любиш ти Мене більше, ніж вони? Петро каже Йому: так, Господи! Ти знаєш, що я люблю Тебе. Ісус говорить йому: паси ягнят Моїх.","Ще говорить йому вдруге: Симоне Іонин! Чи любиш ти Мене? Петро говорить Йому: так, Господи! Ти знаєш, що я люблю Тебе. Ісус говорить йому: паси вівці Мої.","Говорить йому втретє: Симоне Іонин! Чи любиш ти Мене? Петро засмутився, що втретє спитав його: чи любиш ти Мене? І сказав Йому: Господи! Ти все знаєш: Ти знаєш, що я люблю Тебе. Ісус говорить йому: паси вівці Мої.","Істинно, істинно кажу тобі: коли ти був молодий, то підперізувався сам і ходив, куди хотів; коли ж постарієш, то простягнеш руки твої й інший підпереже тебе і поведе, куди не хочеш.","Це Він сказав, щоб зрозуміли, якою смертю Петро прославить Бога. І, сказавши це, говорить йому: йди за Мною.","Петро ж, обернувшись, бачить, що йде за ним ученик, якого любив Ісус і який на вечері, припавши до грудей Його, сказав: Господи, хто видасть Тебе?","Побачивши його, Петро говорить Ісусові: Господи, а він що?","Ісус говорить йому: якщо Я хочу, щоб він залишився, доки прийду, що тобі до того? Ти йди за Мною.","І рознеслося це слово поміж браттями, що ученик той не помре. Але Ісус не сказав йому, що не помре, але: якщо Я хочу, щоб він залишився, доки прийду, що тобі до того?","Це той ученик, що свідчить про це і написав це; і знаємо, що правдиве свідчення його.","Багато й іншого сотворив Ісус; але, коли б написати про те докладно, то, думаю, і сам світ не вмістив би написаних книг. Амінь."],"x":{"1":"50.28.7","4":"52.24.16","13":"54.10.41","16":"54.20.28|56.5.2","18":"57.1.14","20":"53.13.23","24":"53.19.35","25":"53.20.30"}}];
export default C;
